def _find_ffmpeg_binary() -> str:
    """Tìm ffmpeg theo ENV/PATH/vị trí phổ biến trên Windows."""
    env_path = str(os.environ.get('FFMPEG_PATH') or '').strip()
    project_root = os.path.dirname(os.path.abspath(__file__))
    candidates = [
        env_path,
        shutil.which('ffmpeg'),
        shutil.which('ffmpeg.exe'),
        os.path.join(project_root, 'ffmpeg', 'bin', 'ffmpeg.exe'),
        os.path.join(project_root, 'tools', 'ffmpeg', 'bin', 'ffmpeg.exe'),
        r'C:\ffmpeg\bin\ffmpeg.exe',
        r'C:\Program Files\ffmpeg\bin\ffmpeg.exe',
    ]
    for c in candidates:
        if not c:
            continue
        if os.path.isfile(c):
            return c
    return ''


def _ffmpeg_source_has_audio(ffmpeg: str, src: str) -> bool:
    try:
        import subprocess
        proc = subprocess.run(
            [ffmpeg, '-hide_banner', '-i', src],
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
        )
        text = (proc.stderr or b'').decode('utf-8', errors='ignore').lower()
        return 'audio:' in text
    except Exception:
        return False


def _ffmpeg_build_atempo_chain(speed: float) -> str:
    filters = []
    remaining = float(speed)
    while remaining > 2.0 + 1e-6:
        filters.append('atempo=2.0')
        remaining /= 2.0
    while remaining < 0.5 - 1e-6:
        filters.append('atempo=0.5')
        remaining /= 0.5
    filters.append(f'atempo={remaining:.6f}')
    return ','.join(filters)


def _speed_label_for_filename(speed: float) -> str:
    s = f'{speed:.2f}'.rstrip('0').rstrip('.')
    return s.replace('.', 'p')


# ===== Ultrasound live stream (RTMP) =====
_ULTRASOUND_LIVE_LOCK = threading.Lock()
_ULTRASOUND_LIVE_SESSIONS = {}


def _ultrasound_live_cleanup_session(session_id: str):
    with _ULTRASOUND_LIVE_LOCK:
        info = _ULTRASOUND_LIVE_SESSIONS.pop(session_id, None)
    if not info:
        return
    workers = info.get('workers') or []
    for w in workers:
        stdin = w.get('stdin')
        proc = w.get('proc')
        if stdin:
            try:
                stdin.close()
            except Exception:
                pass
        if proc:
            try:
                if proc.poll() is None:
                    proc.terminate()
                    try:
                        proc.wait(timeout=2)
                    except Exception:
                        proc.kill()
            except Exception:
                pass


def _ultrasound_build_rtmp_target(rtmp_url: str, stream_key: str) -> str:
    base = str(rtmp_url or '').strip()
    key = str(stream_key or '').strip()
    if not base:
        return ''
    if not key:
        return base
    return f"{base.rstrip('/')}/{key.lstrip('/')}"

