def _get_or_404(model, pk):
    """Lấy bản ghi theo PK, abort(404) nếu không tồn tại (tương thích SQLAlchemy 2.0)."""
    obj = db.session.get(model, pk)
    if obj is None:
        abort(404)
    return obj

