def require_auth(fn):
    def wrapper(*args, **kwargs):
        auth_header = request.headers.get('Authorization', '')
        token = None
        if auth_header.startswith('Bearer '):
            token = auth_header.split(' ', 1)[1].strip()
        if not token:
            token = (request.cookies.get('auth_token') or '').strip() or None
        user_id = get_user_from_token(token)
        if not user_id:
            return jsonify({'error': 'Unauthorized'}), 401
        user = db.session.get(User, user_id)
        if not user:
            return jsonify({'error': 'Unauthorized'}), 401
        if getattr(user, 'must_change_password', False) and request.path not in ('/api/change-password', '/api/logout'):
            return jsonify({
                'error': 'Vui lòng đổi mật khẩu trước khi tiếp tục',
                'code': 'PASSWORD_CHANGE_REQUIRED'
            }), 403
        kwargs['current_user_id'] = user_id
        return fn(*args, **kwargs)
    wrapper.__name__ = fn.__name__
    return wrapper

def require_permission(permission_key):
    """Decorator yêu cầu quyền cụ thể cho API."""
    def decorator(fn):
        def wrapped(*args, **kwargs):
            auth_header = request.headers.get('Authorization', '')
            token = auth_header.split(' ', 1)[1].strip() if auth_header.startswith('Bearer ') else ''
            if not token:
                token = (request.cookies.get('auth_token') or '').strip()
            user_id = get_user_from_token(token)
            if not user_id:
                return jsonify({'error': 'Unauthorized'}), 401
            user = db.session.get(User, user_id)
            if not user:
                return jsonify({'error': 'Unauthorized'}), 401
            if getattr(user, 'must_change_password', False) and request.path not in ('/api/change-password', '/api/logout'):
                return jsonify({
                    'error': 'Vui lòng đổi mật khẩu trước khi tiếp tục',
                    'code': 'PASSWORD_CHANGE_REQUIRED'
                }), 403
            if not has_permission(user_id, permission_key):
                return jsonify({'error': 'Forbidden'}), 403
            return fn(*args, **kwargs)
        wrapped.__name__ = fn.__name__
        return wrapped
    return decorator

# Security headers cho mọi response (giảm clickjacking, MIME sniffing)
@app.after_request
def add_security_headers(response):
    if not getattr(response, '_security_headers_added', False):
        response.headers['X-Frame-Options'] = 'SAMEORIGIN'
        response.headers['X-Content-Type-Options'] = 'nosniff'
        response.headers['X-XSS-Protection'] = '1; mode=block'
        response.headers['Referrer-Policy'] = 'strict-origin-when-cross-origin'
        # CSP cơ bản (có thể nới lỏng nếu trang cần inline script/style)
        if not response.headers.get('Content-Security-Policy'):
            # Cho phép nhúng Google Maps (iframe) trên các trang như clinic-maps.html
            response.headers['Content-Security-Policy'] = (
                "default-src 'self'; "
                "script-src 'self' 'unsafe-inline' 'unsafe-eval' https://cdnjs.cloudflare.com https://cdn.jsdelivr.net https://unpkg.com; "
                "style-src 'self' 'unsafe-inline' https://cdnjs.cloudflare.com https://fonts.googleapis.com; "
                "font-src 'self' https://cdnjs.cloudflare.com https://fonts.gstatic.com; "
                "img-src 'self' data: https:; "
                "connect-src 'self'; "
                "frame-src 'self' blob: data: https://www.google.com https://maps.google.com https://www.google.com.vn https://www.youtube.com https://www.youtube-nocookie.com; "
                "object-src 'self' blob: data:; "
                "worker-src 'self' blob: https://cdnjs.cloudflare.com https://cdn.jsdelivr.net"
            )
        response._security_headers_added = True
    return _maybe_gzip_response(response)

# Route đăng nhập (fallback - đảm bảo luôn hoạt động)
@app.route('/api/login', methods=['POST'])
def api_login():
    """POST /api/login - Đăng nhập, trả về token"""
    from flask import make_response
    data = request.get_json(silent=True) or request.form or {}
    username = (data.get('username') or '').strip()
    password = data.get('password')
    if not username or not password:
        return jsonify({'error': 'Username and password required'}), 400
    try:
        result = db.session.execute(
            text("SELECT id, username, password_hash, full_name, email, status, must_change_password FROM user WHERE username = :username"),
            {"username": username}
        ).fetchone()
        if not result:
            return jsonify({'error': 'Tên đăng nhập hoặc mật khẩu không đúng'}), 401
        user_id, username_db, password_hash, full_name, email, status, must_change_password = result

        # Verify password tương thích mọi môi trường (kể cả khi werkzeug không hỗ trợ scrypt).
        if not verify_password_hash(password_hash, password):
            # Nếu hash type không được hỗ trợ, trả message rõ ràng (để user reset)
            if isinstance(password_hash, str) and password_hash.startswith('scrypt:'):
                return jsonify({
                    'error': 'Tài khoản này đang dùng chuẩn mật khẩu cũ trên môi trường web. Vui lòng dùng chức năng "Quên mật khẩu" để đặt lại mật khẩu mới.',
                    'code': 'UNSUPPORTED_PASSWORD_HASH'
                }), 400
            return jsonify({'error': 'Tên đăng nhập hoặc mật khẩu không đúng'}), 401

        # Nếu đăng nhập đúng bằng hash scrypt thì tự động nâng cấp sang pbkdf2 để đồng bộ web/local
        try:
            if isinstance(password_hash, str) and password_hash.startswith('scrypt:'):
                new_hash = hash_password(password)
                db.session.execute(
                    text("UPDATE user SET password_hash = :ph WHERE id = :uid"),
                    {"ph": new_hash, "uid": user_id}
                )
                db.session.commit()
        except Exception:
            # Không làm fail login nếu migrate hash lỗi
            try:
                db.session.rollback()
            except Exception:
                pass
        if status != 'active':
            return jsonify({'error': 'Tài khoản đã bị vô hiệu hóa'}), 401
        ip_address = request.remote_addr or ''
        user_agent = request.headers.get('User-Agent', '')

        # URL/host nội bộ tin cậy: cho phép đăng nhập không cần phê duyệt máy lạ.
        if _is_login_approval_bypass_request(request, ip_address):
            trusted = TrustedLoginIP.query.filter_by(user_id=user_id, ip_address=ip_address).first()
            if trusted is None:
                trusted = TrustedLoginIP(
                    user_id=user_id,
                    ip_address=ip_address,
                    user_agent=user_agent,
                    created_at=datetime.utcnow(),
                    is_approved=True,
                    approval_token=__import__('secrets').token_urlsafe(32),
                    approved_at=datetime.utcnow()
                )
                db.session.add(trusted)
            else:
                trusted.user_agent = user_agent or trusted.user_agent
                trusted.is_approved = True
                trusted.approved_at = datetime.utcnow()
            db.session.commit()

        # Máy lạ bắt buộc phải được admin phê duyệt trong tab "Phiên đăng nhập / IP"
        trusted = TrustedLoginIP.query.filter_by(user_id=user_id, ip_address=ip_address).first()
        if trusted is None or not trusted.is_approved:
            approval_token = __import__('secrets').token_urlsafe(32)
            if trusted is None:
                trusted = TrustedLoginIP(
                    user_id=user_id,
                    ip_address=ip_address,
                    user_agent=user_agent,
                    created_at=datetime.utcnow(),
                    is_approved=False,
                    approval_token=approval_token
                )
                db.session.add(trusted)
            else:
                trusted.user_agent = user_agent or trusted.user_agent
                trusted.is_approved = False
                trusted.approved_at = None
                trusted.approval_token = approval_token
            db.session.commit()
            return jsonify({
                'error': 'Máy/địa chỉ IP này chưa được phê duyệt. Vui lòng liên hệ admin và phê duyệt ở tab "Phiên đăng nhập / IP".',
                'code': 'LOGIN_DEVICE_PENDING_APPROVAL'
            }), 403

        now_str = datetime.utcnow().strftime('%Y-%m-%d %H:%M:%S')
        db.session.execute(
            text("UPDATE user SET last_login = :now WHERE id = :user_id"),
            {"now": now_str, "user_id": user_id}
        )
        db.session.commit()
        roles_result = db.session.execute(
            text("SELECT r.name FROM role r JOIN user_roles ur ON ur.role_id = r.id WHERE ur.user_id = :user_id"),
            {"user_id": user_id}
        ).fetchall()
        roles = [row[0] for row in roles_result]
        token = __import__('secrets').token_urlsafe(32)
        session_id = register_token(token, user_id, ip_address=ip_address, user_agent=user_agent, is_new_device=False)
        resp = make_response(jsonify({
            'token': token,
            'user': {
                'id': user_id,
                'username': username_db,
                'full_name': full_name or '',
                'email': email or '',
                'roles': roles,
                'must_change_password': bool(must_change_password),
            },
            'session_id': session_id,
            'is_new_device': False,
        }))
        resp.set_cookie('auth_token', token, httponly=True, samesite='Lax', max_age=TOKEN_TTL_SECONDS)
        return resp
    except Exception as e:
        import traceback
        traceback.print_exc()
        err_detail = str(e) if app.config.get('DEBUG') else None
        return jsonify({'error': 'Lỗi hệ thống', 'detail': err_detail}), 500

@app.route('/api/logout', methods=['POST'])
def api_logout():
    """POST /api/logout - Xóa cookie auth"""
    auth_header = request.headers.get('Authorization', '')
    token = auth_header.split(' ', 1)[1] if auth_header.startswith('Bearer ') else (request.cookies.get('auth_token') or auth_header)
    if token:
        _ensure_auth_session_table()
        _maybe_cleanup_auth_sessions()
        try:
            row = AuthSession.query.filter_by(token=token).first()
            if row:
                row.revoked = True
                db.session.commit()
        except Exception:
            db.session.rollback()
        try:
            TOKENS.pop(token, None)
        except Exception:
            pass
    resp = jsonify({'message': 'Đã đăng xuất'})
    resp.set_cookie('auth_token', '', max_age=0, expires=0)
    return resp

@app.route('/api/login-verify-otp', methods=['POST'])
def api_login_verify_otp():
    """Xác minh OTP khi đăng nhập từ máy lạ."""
    data = request.get_json(silent=True) or {}
    temp_token = (data.get('temp_token') or '').strip()
    otp = (data.get('otp') or '').strip().replace(' ', '')
    if not temp_token or not otp:
        return jsonify({'error': 'Vui lòng nhập mã OTP'}), 400
    entry = LOGIN_OTP_STORE.get(temp_token)
    if not entry:
        return jsonify({'error': 'Phiên OTP đã hết hạn. Vui lòng đăng nhập lại.'}), 400
    if entry['expires_at'] < datetime.utcnow():
        try:
            del LOGIN_OTP_STORE[temp_token]
        except Exception:
            pass
        return jsonify({'error': 'Mã OTP đã hết hạn. Vui lòng đăng nhập lại và gửi mã mới.'}), 400
    if entry['otp'] != otp:
        return jsonify({'error': 'Mã OTP không đúng. Vui lòng thử lại.'}), 400
    # Xác minh IP trùng với lúc gửi OTP
    ip_address = request.remote_addr or ''
    if entry['ip_address'] != ip_address:
        return jsonify({'error': 'Địa chỉ IP không khớp. Vui lòng đăng nhập lại.'}), 400
    user_id = entry['user_id']
    username_db = entry['username']
    ip_address = entry['ip_address']
    user_agent = entry.get('user_agent', '')
    try:
        del LOGIN_OTP_STORE[temp_token]
    except Exception:
        pass
    # Thêm IP vào danh sách tin cậy
    trusted = TrustedLoginIP.query.filter_by(user_id=user_id, ip_address=ip_address).first()
    if trusted is None:
        trusted = TrustedLoginIP(
            user_id=user_id,
            ip_address=ip_address,
            user_agent=user_agent,
            created_at=datetime.utcnow(),
            is_approved=True,
            approval_token=__import__('secrets').token_urlsafe(32),
            approved_at=datetime.utcnow()
        )
        db.session.add(trusted)
    else:
        trusted.is_approved = True
        trusted.approved_at = datetime.utcnow()
    db.session.commit()
    now_str = datetime.utcnow().strftime('%Y-%m-%d %H:%M:%S')
    db.session.execute(
        text("UPDATE user SET last_login = :now WHERE id = :user_id"),
        {"now": now_str, "user_id": user_id}
    )
    db.session.commit()
    result = db.session.execute(
        text("SELECT full_name, email, must_change_password FROM user WHERE id = :uid"),
        {"uid": user_id}
    ).fetchone()
    full_name, email, must_change_password = result or ('', '', False)
    roles_result = db.session.execute(
        text("SELECT r.name FROM role r JOIN user_roles ur ON ur.role_id = r.id WHERE ur.user_id = :user_id"),
        {"user_id": user_id}
    ).fetchall()
    roles = [row[0] for row in roles_result]
    token = __import__('secrets').token_urlsafe(32)
    session_id = register_token(token, user_id, ip_address=ip_address, user_agent=user_agent, is_new_device=False)
    resp = make_response(jsonify({
        'token': token,
        'user': {
            'id': user_id,
            'username': username_db,
            'full_name': full_name or '',
            'email': email or '',
            'roles': roles,
            'must_change_password': bool(must_change_password),
        },
        'session_id': session_id,
        'is_new_device': False,
    }))
    resp.set_cookie('auth_token', token, httponly=True, samesite='Lax', max_age=TOKEN_TTL_SECONDS)
    return resp

@app.route('/api/login-resend-otp', methods=['POST'])
def api_login_resend_otp():
    """Gửi lại mã OTP khi đăng nhập từ máy lạ. Chỉ được gọi sau 30 giây."""
    data = request.get_json(silent=True) or {}
    temp_token = (data.get('temp_token') or '').strip()
    if not temp_token:
        return jsonify({'error': 'Thiếu temp_token'}), 400
    entry = LOGIN_OTP_STORE.get(temp_token)
    if not entry:
        return jsonify({'error': 'Phiên OTP đã hết hạn. Vui lòng đăng nhập lại.'}), 400
    if entry['expires_at'] < datetime.utcnow():
        try:
            del LOGIN_OTP_STORE[temp_token]
        except Exception:
            pass
        return jsonify({'error': 'Phiên đã hết hạn. Vui lòng đăng nhập lại.'}), 400
    now = datetime.utcnow()
    elapsed = (now - entry['last_sent_at']).total_seconds()
    if elapsed < OTP_RESEND_COOLDOWN_SECONDS:
        return jsonify({
            'error': f'Vui lòng đợi {int(OTP_RESEND_COOLDOWN_SECONDS - elapsed)} giây nữa để gửi mã mới.',
            'next_available_seconds': int(OTP_RESEND_COOLDOWN_SECONDS - elapsed)
        }), 429
    ip_address = request.remote_addr or ''
    if entry['ip_address'] != ip_address:
        return jsonify({'error': 'Địa chỉ IP không khớp.'}), 400
    import random
    otp = ''.join([str(random.randint(0, 9)) for _ in range(6)])
    entry['otp'] = otp
    entry['last_sent_at'] = now
    entry['expires_at'] = now + timedelta(seconds=OTP_VALID_SECONDS)
    user_email = db.session.execute(
        text("SELECT email FROM user WHERE id = :uid"),
        {"uid": entry['user_id']}
    ).scalar() or ''
    if not user_email:
        return jsonify({'error': 'Không lấy được email người dùng.'}), 500
    send_login_otp_email(user_email.strip(), otp)
    return jsonify({
        'message': 'Mã OTP mới đã gửi đến email của bạn.',
        'next_available_seconds': OTP_RESEND_COOLDOWN_SECONDS
    })

@app.route('/api/change-password', methods=['POST'])
@require_auth
def api_change_password(current_user_id):
    """Cho phép người dùng đã đăng nhập đổi mật khẩu của chính mình."""
    data = request.get_json(silent=True) or {}
    current_password = (data.get('current_password') or '').strip()
    new_password = (data.get('new_password') or '').strip()
    if not current_password or not new_password:
        return jsonify({'error': 'Vui lòng nhập đầy đủ mật khẩu hiện tại và mật khẩu mới'}), 400
    user = db.session.get(User, current_user_id)
    if not user:
        return jsonify({'error': 'Tài khoản không tồn tại'}), 404
    if not verify_password_hash(user.password_hash, current_password):
        return jsonify({'error': 'Mật khẩu hiện tại không đúng'}), 400
    ok, msg = validate_password_strength(new_password)
    if not ok:
        return jsonify({'error': msg}), 400
    user.password_hash = hash_password(new_password)
    user.must_change_password = False
    user.password_changed_at = datetime.utcnow()
    db.session.commit()
    return jsonify({'message': 'Đã đổi mật khẩu thành công'})

@app.route('/api/login-approvals/approve', methods=['GET'])
def api_approve_login_device():
    """Endpoint cho admin phê duyệt đăng nhập từ máy mới thông qua link trong email."""
    token = request.args.get('token', '').strip()
    if not token:
        return Response("Thiếu token phê duyệt.", mimetype='text/plain; charset=utf-8'), 400
    rec = TrustedLoginIP.query.filter_by(approval_token=token).first()
    if not rec:
        return Response("Yêu cầu phê duyệt không tồn tại hoặc đã bị xóa.", mimetype='text/plain; charset=utf-8'), 404
    if rec.is_approved:
        return Response("Máy/địa chỉ IP này đã được phê duyệt trước đó.", mimetype='text/plain; charset=utf-8')
    rec.is_approved = True
    rec.approved_at = datetime.utcnow()
    db.session.commit()
    return Response(
        f"ĐÃ PHÊ DUYỆT: Tài khoản ID {rec.user_id} được phép đăng nhập từ IP {rec.ip_address}. "
        f"Người dùng có thể đăng nhập lại từ máy này.",
        mimetype='text/plain; charset=utf-8'
    )

@app.route('/api/login-approvals/deny', methods=['GET'])
def api_deny_login_device():
    """Endpoint cho admin từ chối đăng nhập từ máy mới thông qua link trong email."""
    token = request.args.get('token', '').strip()
    if not token:
        return Response("Thiếu token từ chối.", mimetype='text/plain; charset=utf-8'), 400
    rec = TrustedLoginIP.query.filter_by(approval_token=token).first()
    if not rec:
        return Response("Yêu cầu phê duyệt không tồn tại hoặc đã bị xóa.", mimetype='text/plain; charset=utf-8'), 404
