def _sync_token_ok(req, body: dict = None) -> bool:
    expected = (os.environ.get('SYNC_TOKEN') or app.config.get('SYNC_TOKEN') or '').strip()
    if not expected:
        return False
    got = (req.headers.get('X-Sync-Token') or (body or {}).get('token') or '').strip()
    if not got:
        return False
    return hmac.compare_digest(got.encode('utf-8'), expected.encode('utf-8'))


def _pacs_internal_token_ok(req) -> bool:
    """Xác thực callback nội bộ từ dicom_receiver (LAN)."""
    expected = (
        os.environ.get('PACS_INTERNAL_TOKEN')
        or app.config.get('PACS_INTERNAL_TOKEN')
        or os.environ.get('SYNC_TOKEN')
        or app.config.get('SYNC_TOKEN')
        or ''
    ).strip()
    if not expected:
        remote = (req.remote_addr or '').strip()
        return remote in ('127.0.0.1', '::1')
    got = (req.headers.get('X-PACS-Token') or req.headers.get('X-Sync-Token') or '').strip()
    if not got:
        return False
    return hmac.compare_digest(got.encode('utf-8'), expected.encode('utf-8'))


def _auth_token_from_request():
    auth_header = request.headers.get('Authorization', '')
    if auth_header.startswith('Bearer '):
        return auth_header.split(' ', 1)[1].strip()
    return (request.cookies.get('auth_token') or '').strip() or None


def _require_staff_api_access(fn):
    """API DICOM/PACS: nhân viên đã đăng nhập hoặc token nội bộ (dicom_receiver)."""
    def wrapped(*args, **kwargs):
        if request.method == 'OPTIONS':
            return fn(*args, **kwargs)
        if _pacs_internal_token_ok(request):
            return fn(*args, **kwargs)
        user_id = get_user_from_token(_auth_token_from_request())
        if not user_id:
            return jsonify({'error': 'Unauthorized'}), 401
        return fn(*args, **kwargs)
    wrapped.__name__ = fn.__name__
    return wrapped


def _parse_appointment_datetime(value):
    if value is None or value == '':
        return None
    s = str(value).strip().replace('Z', '+00:00')
    try:
        return datetime.fromisoformat(s)
    except Exception:
        pass
    for fmt in ('%Y-%m-%d %H:%M:%S.%f', '%Y-%m-%d %H:%M:%S', '%Y-%m-%d %H:%M', '%Y-%m-%d'):
        try:
            return datetime.strptime(s[:26], fmt)
        except Exception:
            continue
    return None


def _apply_legacy_sync_appointment_payload(appt_data: dict, action: str = 'insert') -> None:
    """Áp dụng lịch khám từ sync_queue hoặc POST /api/sync/appointment (định dạng cũ)."""
    appt_data = appt_data or {}
    global_id = (appt_data.get('global_id') or '').strip()
    if not global_id:
        raise ValueError('missing global_id')

    patient = None
    pid = appt_data.get('patient_id')
    if pid is not None:
        try:
            patient = Patient.query.get(int(pid))
        except Exception:
            patient = None
    if not patient:
        raise ValueError('patient not found')

    appt_dt = _parse_appointment_datetime(appt_data.get('appointment_date'))
    event_type = 'appointment.updated' if (action or '').lower() == 'update' else 'appointment.created'
    payload = {
        'appointment': {
            'global_id': global_id,
            'appointment_date': appt_dt.isoformat() if appt_dt else appt_data.get('appointment_date'),
            'service_type': appt_data.get('service_type'),
            'status': appt_data.get('status'),
            'doctor_name': appt_data.get('doctor_name'),
            'source': appt_data.get('source') or 'local',
        },
        'patient': _sync_patient_payload(patient),
    }
    _apply_sync_event(event_type, payload)

def _emit_sync_event(entity: str, global_id: str, event_type: str, payload_obj: dict) -> None:
    """Ghi event để đồng bộ (best-effort)."""
    if not global_id:
        return
    try:
        ev = SyncEvent(
            event_id=str(uuid.uuid4()),
            entity=entity,
            global_id=global_id,
            event_type=event_type,
            payload=json.dumps(payload_obj or {}, ensure_ascii=False),
        )
        db.session.add(ev)
        db.session.commit()
    except Exception:
        db.session.rollback()

def _http_json(method: str, url: str, headers: dict = None, body_obj=None, timeout_s: int = 15):
    """Gọi HTTP JSON dùng urllib (không phụ thuộc requests)."""
    req_headers = {'Content-Type': 'application/json'}
    if headers:
        req_headers.update(headers)
    data = None
    if body_obj is not None:
        data = json.dumps(body_obj, ensure_ascii=False).encode('utf-8')
    req = urllib.request.Request(url=url, data=data, headers=req_headers, method=method.upper())
    try:
        with urllib.request.urlopen(req, timeout=timeout_s) as resp:
            raw = resp.read()
            text_body = raw.decode('utf-8', errors='replace') if raw else ''
            if not text_body:
                return resp.getcode(), {}
            try:
                return resp.getcode(), json.loads(text_body)
            except Exception:
                return resp.getcode(), {'raw': text_body}
    except urllib.error.HTTPError as e:
        raw = e.read()
        text_body = raw.decode('utf-8', errors='replace') if raw else ''
        try:
            return e.code, json.loads(text_body) if text_body else {}
        except Exception:
            return e.code, {'raw': text_body}
    except Exception as e:
        return 0, {'error': str(e)}

def _mirror_appointment_create_to_peer(payload: dict) -> None:
    """Best-effort mirror đăng ký khám sang node peer để đảm bảo hiển thị 2 chiều."""
    try:
        peer_base = (os.environ.get('SYNC_PEER_APPOINTMENTS_URL') or app.config.get('SYNC_PEER_APPOINTMENTS_URL') or '').strip().rstrip('/')
        if not peer_base:
            return
        token = (os.environ.get('SYNC_PEER_TOKEN') or app.config.get('SYNC_PEER_TOKEN') or '').strip()
        headers = {'X-Appointment-Mirror': '1'}
        if token:
            headers['X-Sync-Token'] = token
        _http_json(
            'POST',
            f"{peer_base}/api/appointments",
            headers=headers,
            body_obj=payload or {},
            timeout_s=10,
        )
    except Exception:
        # Không làm hỏng luồng đăng ký gốc nếu peer lỗi mạng.
        pass

