def _sync_appointment_diagnosis(appointment_id, patient_id, diagnosis_text):
    """Upsert MedicalRecord.diagnosis for appointment so examination-list shows it."""
    diag = (diagnosis_text or '').strip()
    if not appointment_id or not patient_id or not diag:
        return False
    try:
        appt = db.session.get(Appointment, int(appointment_id))
        if not appt:
            return False
        pid = int(patient_id)
        if appt.patient_id and int(appt.patient_id) != pid:
            # Prefer appointment's patient; still allow sync if IDs match intent
            pid = int(appt.patient_id)
        rec = MedicalRecord.query.filter_by(appointment_id=int(appointment_id)).order_by(MedicalRecord.id.desc()).first()
        if not rec:
            rec = MedicalRecord(patient_id=pid, appointment_id=int(appointment_id))
            db.session.add(rec)
        # Keep short for list view; preserve existing longer text if new is empty already handled
        rec.diagnosis = diag[:2000]
        rec.patient_id = pid
        return True
    except Exception as e:
        print(f"⚠️ sync appointment diagnosis failed: {e}")
        return False

def normalize_service_group_name(name):
    return (name or '').strip().lower()

def get_lab_settings_record(auto_commit=True):
    ensure_lab_settings_columns()
    settings = LabSettings.query.first()
    if not settings:
        settings = LabSettings()
        db.session.add(settings)
        if auto_commit:
            db.session.commit()
    return settings

def get_service_group_list(auto_commit=True):
    ensure_clinical_service_setting_columns()
    settings = get_lab_settings_record(auto_commit=auto_commit)
    try:
        raw = getattr(settings, 'service_group_list', None)
    except AttributeError:
        raw = None
    groups = []
    if raw:
        try:
            groups = json.loads(raw)
        except Exception:
            groups = []
    if not groups:
        try:
            distinct_groups = db.session.query(ClinicalServiceSetting.service_group).filter(
                ClinicalServiceSetting.service_group.isnot(None)
            ).distinct().all()
            groups = [g[0] for g in distinct_groups if g[0]]
        except Exception:
            groups = []
    if not groups:
        groups = DEFAULT_CLINICAL_SERVICE_GROUPS.copy()

    cleaned_groups = []
    seen = set()
    for group in groups:
        label = (group or '').strip()
        if not label:
            continue
        norm = normalize_service_group_name(label)
        if norm in seen:
            continue
        seen.add(norm)
        cleaned_groups.append(label)
    groups = cleaned_groups

    serialized = json.dumps(groups, ensure_ascii=False)
    if getattr(settings, 'service_group_list', None) != serialized:
        settings.service_group_list = serialized
        if auto_commit:
            db.session.commit()

    return groups, settings

def save_service_groups(groups, settings=None, commit=True):
    settings = settings or get_lab_settings_record(auto_commit=False)
    settings.service_group_list = json.dumps(groups, ensure_ascii=False)
    if commit:
        db.session.commit()

def ensure_service_group_tracked(service_group, commit_changes=False):
    label = (service_group or '').strip()
    if not label:
        return
    groups, settings = get_service_group_list(auto_commit=False)
    normalized = normalize_service_group_name(label)
    if any(normalize_service_group_name(g) == normalized for g in groups):
        return
    groups.append(label)
    save_service_groups(groups, settings=settings, commit=commit_changes)

def make_service_group_slug(name):
    raw = (name or '').strip().lower()
    if not raw:
        return 'other-test'
    normalized = unicodedata.normalize('NFKD', raw)
    ascii_text = normalized.encode('ascii', 'ignore').decode('ascii')
    slug = re.sub(r'[^a-z0-9]+', '-', ascii_text).strip('-')
    return slug or 'other-test'

