DEFAULT_SLOT_MINUTES_KEY = 'work_schedule_default_slot_minutes'
DEFAULT_SLOT_MINUTES_FALLBACK = 10

def _sanitize_slot_minutes(value, fallback=DEFAULT_SLOT_MINUTES_FALLBACK):
    try:
        minutes = int(value)
        if minutes <= 0:
            return fallback
        return min(minutes, 240)
    except (TypeError, ValueError):
        return fallback

@app.route('/api/artificial-cycle/default-offset', methods=['GET', 'POST'])
def artificial_cycle_default_offset():
    try:
        # ensure tables exist (safe)
        try:
            db.create_all()
        except Exception:
            pass
        if request.method == 'GET':
            val = AppSetting.get_value('art_cycle_default_offset_days', '14')
            try:
                days = int(val)
            except (TypeError, ValueError):
                days = 14
            return jsonify({'success': True, 'offset_days': days})
        else:
            data = request.json or {}
            raw = data.get('offset_days')
            try:
                days = int(raw)
                if days < 0:
                    return jsonify({'success': False, 'message': 'Số ngày phải >= 0'}), 400
            except (TypeError, ValueError):
                return jsonify({'success': False, 'message': 'Giá trị không hợp lệ'}), 400
            AppSetting.set_value('art_cycle_default_offset_days', str(days))
            return jsonify({'success': True, 'offset_days': days, 'message': 'Đã lưu mặc định thành công'})
    except Exception as e:
        db.session.rollback()
        return jsonify({'success': False, 'message': str(e)}), 500

@app.route('/api/admin/work-schedule/default-slot-minutes', methods=['GET', 'POST'])
def work_schedule_default_slot_minutes():
    try:
        try:
            db.create_all()
        except Exception:
            pass

        if request.method == 'GET':
            minutes = _sanitize_slot_minutes(
                AppSetting.get_value(DEFAULT_SLOT_MINUTES_KEY, str(DEFAULT_SLOT_MINUTES_FALLBACK))
            )
            return jsonify({'success': True, 'slot_minutes': minutes})

        payload = request.get_json(silent=True) or {}
        raw_minutes = payload.get('slot_minutes')
        try:
            minutes = int(raw_minutes)
        except (TypeError, ValueError):
            return jsonify({'success': False, 'message': 'Giá trị phút không hợp lệ'}), 400

        if minutes < 1 or minutes > 240:
            return jsonify({'success': False, 'message': 'Số phút phải từ 1 đến 240'}), 400

        AppSetting.set_value(DEFAULT_SLOT_MINUTES_KEY, str(minutes))
        return jsonify({
            'success': True,
            'slot_minutes': minutes,
            'message': 'Đã cập nhật số phút khám mặc định'
        })
    except Exception as e:
        db.session.rollback()
        return jsonify({'success': False, 'message': str(e)}), 500

# Routes
_DICOM_AUTOSTART_LOCK = threading.Lock()
_DICOM_AUTOSTART_LAST_TRY = {}
_DICOM_AUTOSTART_COOLDOWN_SECONDS = 15
DICOM_MWL_PORT = int(os.environ.get('DICOM_MWL_PORT', '104') or '104')
DICOM_CSTORE_PORT = int(os.environ.get('DICOM_CSTORE_PORT', '11112') or '11112')


def _is_local_port_open(port: int, timeout_sec: float = 0.6) -> bool:
    try:
        s = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        s.settimeout(timeout_sec)
        code = s.connect_ex(('127.0.0.1', int(port)))
        s.close()
        return code == 0
    except Exception:
        return False


def _ensure_dicom_script_running(script_name: str, port: int, state_key: str) -> bool:
    """Khởi động nền mwl_server.py hoặc dicom_receiver.py nếu port chưa mở."""
    global _DICOM_AUTOSTART_LAST_TRY
    if _is_local_port_open(port):
        return True

    now = datetime.utcnow()
    with _DICOM_AUTOSTART_LOCK:
        if _is_local_port_open(port):
            return True
        last_try = _DICOM_AUTOSTART_LAST_TRY.get(state_key)
        if last_try is not None:
            elapsed = (now - last_try).total_seconds()
            if elapsed < _DICOM_AUTOSTART_COOLDOWN_SECONDS:
                return False
        _DICOM_AUTOSTART_LAST_TRY[state_key] = now

        script_path = (Path(__file__).resolve().parent / script_name)
        if not script_path.exists():
            print(f"[DICOM-AUTOSTART:{state_key}] Không tìm thấy {script_name}")
            return False

        try:
            popen_kwargs = {
                'cwd': str(script_path.parent),
                'stdin': subprocess.DEVNULL,
                'stdout': subprocess.DEVNULL,
                'stderr': subprocess.DEVNULL,
                'close_fds': True,
            }
            if os.name == 'nt':
                popen_kwargs['creationflags'] = (
                    getattr(subprocess, 'DETACHED_PROCESS', 0)
                    | getattr(subprocess, 'CREATE_NEW_PROCESS_GROUP', 0)
                )
            subprocess.Popen([sys.executable, str(script_path)], **popen_kwargs)
            print(f"[DICOM-AUTOSTART:{state_key}] Đã khởi động {script_name} (port {port})")
        except Exception as e:
            print(f"[DICOM-AUTOSTART:{state_key}] Không thể khởi động {script_name}: {e}")
            return False
    return False


def _ensure_mwl_server_running() -> bool:
    """Auto-start MWL server on port 104 when web is opened."""
    return _ensure_dicom_script_running('mwl_server.py', DICOM_MWL_PORT, 'mwl')


def _ensure_dicom_receiver_running() -> bool:
    """Auto-start C-STORE receiver on port 11112 khi mở web (VR PACS / worklist)."""
    return _ensure_dicom_script_running('dicom_receiver.py', DICOM_CSTORE_PORT, 'cstore')


def _mwl_sync_days_ahead() -> int:
    """Số ngày tới đồng bộ MWL (hôm nay + N ngày). Mặc định 7."""
    try:
        raw = AppSetting.get_value('mwl_sync_days_ahead', '') or os.environ.get('MWL_SYNC_DAYS_AHEAD', '7')
        days = int(str(raw).strip())
    except Exception:
        days = 7
    return max(0, min(days, 30))


def _mwl_appointment_date_sql(alias: str = 'a') -> str:
    """Điều kiện SQL lọc ngày hẹn cho MWL sync."""
    col = f"date({alias}.appointment_date)"
    days = _mwl_sync_days_ahead()
    if days <= 0:
        return f"{col} = date('now', 'localtime')"
    return f"{col} BETWEEN date('now', 'localtime') AND date('now', 'localtime', '+{days} day')"


def _request_hostname():
    """Hostname không gồm port (vd. dangki.phusandaianh.io.vn)."""
    return (request.host or '').split(':', 1)[0].lower()


def _is_patient_booking_host():
    """
    Subdomain đăng ký khám công khai (URL giữ nguyên trên thanh địa chỉ).
    Mặc định: dangki.* — cấu hình thêm bằng BOOKING_HOST_PREFIXES (phân tách bằng dấu phẩy).
    """
    host = _request_hostname()
    # Mặc định hỗ trợ cả booking.* và dangki.* (Render subdomain đặt lịch)
    raw = (os.environ.get('BOOKING_HOST_PREFIXES') or 'booking.,dangki.').strip()
    for prefix in raw.split(','):
        prefix = prefix.strip().lower()
        if prefix and host.startswith(prefix):
            return True
    return False


def _serve_patient_booking_page():
    """Trang đặt lịch bệnh nhân (booking.html ở thư mục gốc app)."""
    return send_from_directory('.', 'booking.html')


@app.before_request
def auto_start_mwl_for_main_pages():
    """
    Đảm bảo MWL server chạy khi người dùng mở các trang giao diện chính.
    Áp dụng cho GET / và các URL .html, bỏ qua API/static nhị phân.
    """
    try:
        if request.method != 'GET':
            return
        path = (request.path or '').lower()
        if path.startswith('/api/') or path.startswith('/dicom/'):
            return
        if path == '/' or path.endswith('.html'):
            _ensure_mwl_server_running()
            # C-STORE cần cho nhận ảnh VR PACS (port 11112)
            if any(k in path for k in ('vr-pacs', 'worklist', 'examination-list', 'ultrasound')):
                _ensure_dicom_receiver_running()
    except Exception as e:
        print(f"[MWL-AUTOSTART] before_request error: {e}")

@app.route('/')
def index():
    # Khi mở trang chủ, đảm bảo MWL server (port 104) đang chạy.
    try:
        _ensure_mwl_server_running()
    except Exception as e:
        print(f"[MWL-AUTOSTART] Lỗi khi kiểm tra/khởi động MWL: {e}")
    if _is_patient_booking_host():
        return _serve_patient_booking_page()
    return render_template('index.html')

