backup_startup_thread.start()

# ===================== SYNC ONLINE <-> LOCAL (Appointment/ChangeRequest) =====================
def _resolve_patient_from_sync_payload(pt: dict):
    """Tìm Patient từ payload đồng bộ (ưu tiên id nội bộ / mã PID / khớp tên+NS+SĐT / SĐT đơn)."""
    phone = (pt.get('phone') or '').strip()
    if not phone:
        return None
    internal = pt.get('patient_internal_id')
    if internal is not None:
        try:
            internal = int(internal)
        except (TypeError, ValueError):
            internal = None
    if internal:
        cand = Patient.query.get(internal)
        if cand and (cand.phone or '').strip() == phone:
            return cand
    pid_bn = (pt.get('patient_pid') or '').strip()
    if pid_bn:
        cand = Patient.query.filter_by(patient_id=pid_bn).first()
        if cand and (cand.phone or '').strip() == phone:
            return cand
    name_n = normalize_patient_display_name(pt.get('name'))
    dob_d = None
    dob_s = pt.get('date_of_birth')
    if dob_s:
        try:
            dob_d = datetime.fromisoformat(str(dob_s).replace('Z', '+00:00')).date()
        except Exception:
            pass
    if name_n and dob_d:
        return (
            Patient.query.filter(
                Patient.phone == phone,
                Patient.name == name_n,
                Patient.date_of_birth == dob_d,
            )
            .order_by(Patient.id.desc())
            .first()
        )
    # Payload cũ chỉ có SĐT: giữ tương thích (bản ghi nhỏ nhất theo id)
    return Patient.query.filter_by(phone=phone).order_by(Patient.id.asc()).first()


def _apply_sync_event(event_type: str, payload_obj: dict) -> None:
    """Áp dụng event vào DB hiện tại. Best-effort, idempotent theo event_id được đảm bảo ở tầng SyncEvent."""
    try:
        if event_type == 'booking_content.updated':
            ensure_booking_reasons_column()
            bc = (payload_obj or {}).get('booking_content') or {}
            content = BookingPageContent.query.first()
            if not content:
                content = BookingPageContent()
                db.session.add(content)
            # Best-effort update; keep existing value when missing
            if bc.get('title') is not None:
                content.title = bc.get('title')
            if bc.get('description') is not None:
                content.description = bc.get('description')
            if bc.get('services') is not None:
                content.services = bc.get('services')
            if bc.get('utilities') is not None:
                content.utilities = bc.get('utilities')
            if bc.get('reasons') is not None:
                content.reasons = bc.get('reasons')
            if bc.get('schedule') is not None:
                content.schedule = bc.get('schedule')
            if bc.get('contact') is not None:
                content.contact = bc.get('contact')
            db.session.commit()
            return

        if event_type in ('appointment.created', 'appointment.updated'):
            ap = (payload_obj or {}).get('appointment') or {}
            pt = (payload_obj or {}).get('patient') or {}
            global_id = (ap.get('global_id') or '').strip()
            if not global_id:
                return

            ensure_appointment_doctor_column()
            ensure_appointment_expected_delivery_date_column()
            ensure_appointment_sync_columns()

            phone = (pt.get('phone') or '').strip()
            if not phone:
                return

            patient = _resolve_patient_from_sync_payload(pt)
            if not patient:
                dob_c = None
                if pt.get('date_of_birth'):
                    try:
                        dob_c = datetime.fromisoformat(str(pt.get('date_of_birth')).replace('Z', '+00:00')).date()
                    except Exception:
                        pass
                patient = _create_patient_with_fresh_bn_pid(
                    name=pt.get('name') or '',
                    phone=phone,
                    address=pt.get('address'),
                    date_of_birth=dob_c,
                )
            else:
                if pt.get('name'):
                    patient.name = normalize_patient_display_name(pt.get('name'))
                if pt.get('address') is not None:
                    patient.address = pt.get('address')
                if pt.get('date_of_birth'):
                    try:
                        patient.date_of_birth = datetime.fromisoformat(str(pt.get('date_of_birth')).replace('Z', '+00:00')).date()
                    except Exception:
                        pass

            appt = Appointment.query.filter_by(global_id=global_id).first()
            if not appt:
                # Create minimal appointment; sẽ được patch thêm sau
                appt = Appointment(
                    patient_id=patient.id,
                    appointment_date=datetime.utcnow(),
                    service_type=ap.get('service_type') or 'Khác',
                    doctor_name=ap.get('doctor_name') or 'PK Đại Anh',
                    global_id=global_id,
                    source=ap.get('source') or 'local',
                    version=ap.get('version') or 1,
                    last_modified_by=ap.get('last_modified_by') or 'system',
                )
                db.session.add(appt)

            if ap.get('appointment_date'):
                try:
                    appt.appointment_date = datetime.fromisoformat(ap.get('appointment_date'))
                except Exception:
                    pass
            if ap.get('service_type') is not None:
                appt.service_type = ap.get('service_type')
            if ap.get('status') is not None:
                appt.status = ap.get('status')
            if ap.get('doctor_name'):
                appt.doctor_name = ap.get('doctor_name')
            if ap.get('source'):
                appt.source = ap.get('source')
            if ap.get('last_modified_by'):
                appt.last_modified_by = ap.get('last_modified_by')
            if ap.get('version'):
                try:
                    appt.version = int(ap.get('version'))
                except Exception:
                    pass
            if ap.get('updated_at'):
                try:
                    appt.updated_at = datetime.fromisoformat(ap.get('updated_at'))
                except Exception:
                    pass
            db.session.commit()
            return

        if event_type == 'appointment.deleted':
            ap = (payload_obj or {}).get('appointment') or {}
            global_id = (ap.get('global_id') or '').strip()
            if not global_id:
                return
            appt = Appointment.query.filter_by(global_id=global_id).first()
            if not appt:
                return

            try:
                ensure_patient_record_columns()
                ensure_patient_record_template_snapshot_table()
                linked_records = PatientRecord.query.filter_by(appointment_id=appt.id).all()
                for pr in linked_records:
                    PatientRecordTemplateSnapshot.query.filter_by(
                        patient_record_id=pr.id
                    ).delete(synchronize_session=False)
                    db.session.delete(pr)
            except Exception:
                pass

            AppointmentChangeRequest.query.filter_by(appointment_id=appt.id).delete(synchronize_session=False)
            Notification.query.filter_by(appointment_id=appt.id).delete(synchronize_session=False)
            MedicalRecord.query.filter_by(appointment_id=appt.id).delete(synchronize_session=False)
            TestResult.query.filter_by(appointment_id=appt.id).delete(synchronize_session=False)
            PatientVital.query.filter_by(appointment_id=appt.id).delete(synchronize_session=False)
            LabOrder.query.filter_by(appointment_id=appt.id).delete(synchronize_session=False)
            for cs in ClinicalService.query.filter_by(appointment_id=appt.id).all():
                try:
                    LabOrder.query.filter_by(clinical_service_id=cs.id).delete(synchronize_session=False)
                except Exception:
                    pass
                db.session.delete(cs)
            db.session.delete(appt)
            db.session.commit()
            return

        if event_type == 'work_schedule.upsert':
            ensure_work_schedule_columns()
            ws = (payload_obj or {}).get('work_schedule') or {}
            external_id = (ws.get('external_id') or '').strip()
            if not external_id:
                return
            row = WorkSchedule.query.filter_by(external_id=external_id).first()
            if not row:
                row = WorkSchedule(external_id=external_id)
                db.session.add(row)
            row.date = ws.get('date') or row.date or datetime.now().strftime('%Y-%m-%d')
            row.start_time = ws.get('start_time') or row.start_time or '00:00'
            row.end_time = ws.get('end_time') or row.end_time or '00:00'
            row.doctor_name = ws.get('doctor_name') or row.doctor_name or 'PK Đại Anh'
            row.is_locked = bool(ws.get('is_locked', False))
            try:
                row.slot_minutes = int(ws.get('slot_minutes', 10) or 10)
            except Exception:
                row.slot_minutes = 10
            row.is_closed = bool(ws.get('is_closed', False))
            db.session.commit()
            return

        if event_type == 'work_schedule.deleted':
            ensure_work_schedule_columns()
            ws = (payload_obj or {}).get('work_schedule') or {}
            external_id = (ws.get('external_id') or '').strip()
            if not external_id:
                return
            row = WorkSchedule.query.filter_by(external_id=external_id).first()
            if not row:
                return
            db.session.delete(row)
            db.session.commit()
            return

        if event_type == 'work_schedule.day_closed':
            ensure_work_schedule_columns()
            ws = (payload_obj or {}).get('work_schedule') or {}
            date = (ws.get('date') or '').strip()
            is_closed = bool(ws.get('is_closed', True))
            if not date:
                return
            updated = WorkSchedule.query.filter_by(date=date).update({WorkSchedule.is_closed: is_closed})
            if updated == 0 and is_closed:
                row = WorkSchedule(
                    external_id=str(uuid.uuid4()),
                    date=date,
                    start_time='00:00',
                    end_time='23:59',
                    doctor_name='Nghỉ',
                    is_locked=True,
                    is_closed=True,
                    slot_minutes=10,
                )
                db.session.add(row)
            db.session.commit()
            return

        if event_type == 'appointment.reschedule_requested':
            cr = (payload_obj or {}).get('change_request') or {}
            ap = (payload_obj or {}).get('appointment') or {}
            request_id = (cr.get('request_id') or '').strip()
            ap_global_id = (cr.get('appointment_global_id') or ap.get('global_id') or '').strip()
            if not request_id or not ap_global_id:
                return

            ensure_appointment_sync_columns()
            appt = Appointment.query.filter_by(global_id=ap_global_id).first()
            if not appt:
                return

            exists = AppointmentChangeRequest.query.filter_by(request_id=request_id).first()
            if exists:
                return

            req = AppointmentChangeRequest(
                request_id=request_id,
                appointment_id=appt.id,
                appointment_global_id=ap_global_id,
                request_type=cr.get('request_type') or 'reschedule',
                requested_date=cr.get('requested_date'),
                requested_time=cr.get('requested_time'),
                status=cr.get('status') or 'pending',
            )
            db.session.add(req)
            db.session.commit()
            return
    except Exception as e:
        print(f"[SYNC] apply event error: {e}")

def _store_and_apply_remote_events(events: list[dict]) -> int:
    latest_seq = 0
    for ev in (events or []):
        try:
            seq = int(ev.get('seq') or 0)
        except Exception:
            seq = 0
        latest_seq = max(latest_seq, seq)

        event_id = (ev.get('event_id') or '').strip()
        if not event_id:
            continue

        if SyncEvent.query.filter_by(event_id=event_id).first():
            continue

        payload_raw = ev.get('payload') or '{}'
        try:
            payload_obj = json.loads(payload_raw) if isinstance(payload_raw, str) else (payload_raw or {})
        except Exception:
            payload_obj = {}

        row = SyncEvent(
            event_id=event_id,
            entity=ev.get('entity') or 'unknown',
            global_id=ev.get('global_id'),
            event_type=ev.get('event_type') or '',
            payload=json.dumps(payload_obj, ensure_ascii=False),
        )
        db.session.add(row)
        db.session.commit()
        _apply_sync_event(row.event_type, payload_obj)
    return latest_seq

@app.route('/api/sync/pull', methods=['GET'])
def api_sync_pull():
    """LOCAL gọi ONLINE để lấy event mới (tăng dần theo seq). Auth: X-Sync-Token."""
    if not _sync_token_ok(request):
        return jsonify({'error': 'Forbidden'}), 403

    since_seq = request.args.get('since_seq', type=int, default=0)
    limit = request.args.get('limit', type=int, default=500)
    limit = max(1, min(limit, 2000))

    rows = SyncEvent.query.filter(SyncEvent.id > since_seq).order_by(SyncEvent.id.asc()).limit(limit).all()
    events = [{
        'seq': r.id,
        'event_id': r.event_id,
        'entity': r.entity,
        'global_id': r.global_id,
        'event_type': r.event_type,
        'payload': r.payload,
    } for r in rows]
    latest_seq = events[-1]['seq'] if events else since_seq
    return jsonify({'latest_seq': latest_seq, 'events': events})

@app.route('/api/sync/push', methods=['POST'])
def api_sync_push():
    """LOCAL đẩy event local lên ONLINE. Auth: X-Sync-Token."""
    if not _sync_token_ok(request):
        return jsonify({'error': 'Forbidden'}), 403
    data = request.json or {}
    events = data.get('events') or []
    if not isinstance(events, list):
        return jsonify({'error': 'events must be a list'}), 400

    accepted = 0
    for ev in events:
        event_id = (ev.get('event_id') or '').strip()
        if not event_id:
            continue
        if SyncEvent.query.filter_by(event_id=event_id).first():
            continue

        payload_raw = ev.get('payload') or '{}'
        try:
            payload_obj = json.loads(payload_raw) if isinstance(payload_raw, str) else (payload_raw or {})
        except Exception:
            payload_obj = {}

        row = SyncEvent(
            event_id=event_id,
            entity=ev.get('entity') or 'unknown',
            global_id=ev.get('global_id'),
            event_type=ev.get('event_type') or '',
            payload=json.dumps(payload_obj, ensure_ascii=False),
        )
        db.session.add(row)
        db.session.commit()
        _apply_sync_event(row.event_type, payload_obj)
        accepted += 1
    return jsonify({'message': 'OK', 'accepted': accepted})


@app.route('/api/sync/work-schedule/reconcile', methods=['POST'])
def api_sync_work_schedule_reconcile():
    if not _sync_token_ok(request, request.json):
        return jsonify({'error': 'Forbidden'}), 403
    data = request.json or {}
    start_date = (data.get('start_date') or '').strip()
    end_date = (data.get('end_date') or '').strip()
    keep = {(x or '').strip() for x in (data.get('external_ids') or []) if (x or '').strip()}
    if not start_date or not end_date:
        return jsonify({'error': 'start_date and end_date required'}), 400
    ensure_work_schedule_columns()
    deleted = 0
    for row in WorkSchedule.query.filter(
        WorkSchedule.date >= start_date,
        WorkSchedule.date <= end_date,
    ).all():
        ext = (getattr(row, 'external_id', None) or '').strip()
        if ext and ext not in keep:
            db.session.delete(row)
            deleted += 1
    db.session.commit()
    return jsonify({'deleted': deleted, 'start_date': start_date, 'end_date': end_date})


def run_sync_loop_local():
    """LOCAL chạy nền: pull từ ONLINE + push event local."""
    import time as _time
    remote = (os.environ.get('SYNC_REMOTE_URL') or app.config.get('SYNC_REMOTE_URL') or '').rstrip('/')
    token = (os.environ.get('SYNC_TOKEN') or app.config.get('SYNC_TOKEN') or '').strip()
    if not remote or not token:
        return

    headers = {'X-Sync-Token': token}
    print(f"[SYNC] local loop started. remote={remote}")
    _sync_state_set(loop_started_at_utc=_utc_iso_now(), last_error=None, last_error_at_utc=None)

    # Khi máy chủ bật lại: đẩy lịch làm việc 30 ngày tới lên Render để bệnh nhân đặt được slot
    try:
        with app.app_context():
            boot = _sync_work_schedules_to_peer_and_events()
            print(
                f"[SYNC] boot schedule push: mirrored={boot.get('mirrored')} "
                f"range={boot.get('start_date')}..{boot.get('end_date')}"
            )
    except Exception as e:
        print(f"[SYNC] boot schedule push skipped: {e}")

    while True:
        try:
            with app.app_context():
                # 1) Pull remote -> local
                last_pulled = int(AppSetting.get_value('sync_last_pulled_seq', 0) or 0)
                code, resp = _http_json('GET', f"{remote}/api/sync/pull?since_seq={last_pulled}&limit=500", headers=headers, timeout_s=20)
                if code == 200 and isinstance(resp, dict):
                    latest = resp.get('latest_seq') or last_pulled
                    events = resp.get('events') or []
                    if events:
                        latest2 = _store_and_apply_remote_events(events)
                        if int(latest2) > last_pulled:
                            AppSetting.set_value('sync_last_pulled_seq', str(int(latest2)))
                        print(f"[SYNC] pulled {len(events)} event(s). latest_seq={latest}")
                    _sync_state_set(last_pull_at_utc=_utc_iso_now(), last_ok_at_utc=_utc_iso_now())

                # 2) Push local -> remote
                last_pushed = int(AppSetting.get_value('sync_last_pushed_seq', 0) or 0)
                to_push = SyncEvent.query.filter(SyncEvent.id > last_pushed).order_by(SyncEvent.id.asc()).limit(500).all()
                if to_push:
                    payload_events = [{
                        'seq': r.id,
                        'event_id': r.event_id,
                        'entity': r.entity,
                        'global_id': r.global_id,
                        'event_type': r.event_type,
                        'payload': r.payload,
                    } for r in to_push]

                    code2, resp2 = _http_json('POST', f"{remote}/api/sync/push", headers=headers, body_obj={'events': payload_events}, timeout_s=20)
                    if code2 == 200:
                        AppSetting.set_value('sync_last_pushed_seq', str(to_push[-1].id))
                        print(f"[SYNC] pushed {len(to_push)} event(s). latest_seq={to_push[-1].id}")
                        _sync_state_set(last_push_at_utc=_utc_iso_now(), last_ok_at_utc=_utc_iso_now())
        except Exception as e:
            print(f"[SYNC] loop error: {e}")
            _sync_state_set(last_error=str(e), last_error_at_utc=_utc_iso_now())

        _time.sleep(int(os.environ.get('SYNC_INTERVAL_SECONDS') or 15))


# ===================== SYNC STATUS (runtime health) =====================
_sync_runtime_state = {
    'loop_started_at_utc': None,
    'last_pull_at_utc': None,
    'last_push_at_utc': None,
    'last_ok_at_utc': None,
    'last_error_at_utc': None,
    'last_error': None,
}


def _utc_iso_now():
    try:
        return datetime.utcnow().replace(microsecond=0).isoformat() + 'Z'
    except Exception:
        return None


def _sync_state_set(**kv):
    try:
        _sync_runtime_state.update(kv)
    except Exception:
        pass


@app.route('/api/sync/status', methods=['GET'])
@require_auth
def api_sync_status(**kwargs):
    """Trạng thái sync để hiển thị cho admin vận hành."""
    role = (os.environ.get('SYNC_ROLE') or app.config.get('SYNC_ROLE') or '').strip().lower() or 'local'
    remote = (os.environ.get('SYNC_REMOTE_URL') or app.config.get('SYNC_REMOTE_URL') or '').strip().rstrip('/')
    token = (os.environ.get('SYNC_TOKEN') or app.config.get('SYNC_TOKEN') or '').strip()

    enabled = bool(role == 'local' and remote and token)
    # Best-effort read stored progress
    try:
        last_pulled_seq = int(AppSetting.get_value('sync_last_pulled_seq', 0) or 0)
    except Exception:
        last_pulled_seq = 0
    try:
        last_pushed_seq = int(AppSetting.get_value('sync_last_pushed_seq', 0) or 0)
    except Exception:
        last_pushed_seq = 0

    return jsonify({
        'role': role,
        'enabled': enabled,
        'remote_url': remote or None,
        'interval_seconds': int(os.environ.get('SYNC_INTERVAL_SECONDS') or 15),
        'last_pulled_seq': last_pulled_seq,
        'last_pushed_seq': last_pushed_seq,
        'runtime': dict(_sync_runtime_state),
    })

# Start sync loop on LOCAL
try:
    if (os.environ.get('SYNC_ROLE') or app.config.get('SYNC_ROLE') or '').strip().lower() == 'local':
        if (os.environ.get('SYNC_REMOTE_URL') or app.config.get('SYNC_REMOTE_URL') or '').strip() and (os.environ.get('SYNC_TOKEN') or app.config.get('SYNC_TOKEN') or '').strip():
            _sync_thread = threading.Thread(target=run_sync_loop_local)
            _sync_thread.daemon = True
            _sync_thread.start()
except Exception:
    pass

