@app.route('/api/booking-content', methods=['POST'])
@require_auth
def update_booking_content(**kwargs):
    # Ensure column exists for older databases
    ensure_booking_reasons_column()
    data = request.json
    content = BookingPageContent.query.first()
    if not content:
        content = BookingPageContent()
        db.session.add(content)
    content.title = data.get('title', content.title)
    content.description = data.get('description', content.description)
    import json
    content.services = json.dumps(data.get('services', []))
    content.utilities = json.dumps(data.get('utilities', []))
    # Handle reasons if present (backward compatible)
    if 'reasons' in data:
        content.reasons = json.dumps(data.get('reasons', []))
    content.schedule = data.get('schedule', content.schedule)
    content.contact = data.get('contact', content.contact)
    db.session.commit()
    # Emit sync event so booking.html content stays consistent across online/local
    try:
        payload = {
            'booking_content': {
                'title': content.title,
                'description': content.description,
                'services': content.services,
                'utilities': content.utilities,
                'reasons': getattr(content, 'reasons', None),
                'schedule': content.schedule,
                'contact': content.contact,
                'updated_at': content.updated_at.isoformat() if content.updated_at else None,
            }
        }
        _emit_sync_event('booking_content', 'booking_content', 'booking_content.updated', payload)
    except Exception:
        pass
    return jsonify({'message': 'Đã cập nhật nội dung trang đặt lịch khám!'})

@app.route('/api/work-schedule', methods=['GET'])
def get_work_schedule():
    ensure_work_schedule_columns()
    today = _today_local_date()
    days = []
    # Lấy tất cả lịch trong 15 ngày tới (hôm nay + 14 ngày sau — đồng bộ trang đặt lịch & nhắc admin)
    all_schedules = WorkSchedule.query.filter(
        WorkSchedule.date >= today.strftime('%Y-%m-%d'),
        WorkSchedule.date <= (today + timedelta(days=14)).strftime('%Y-%m-%d')
    ).order_by(WorkSchedule.date, WorkSchedule.start_time).all()
    # Gom theo ngày
    schedule_dict = {}
    for s in all_schedules:
        if s.date not in schedule_dict:
            schedule_dict[s.date] = []
        schedule_dict[s.date].append({
            'start_time': s.start_time,
            'end_time': s.end_time,
            'doctor_name': s.doctor_name,
            'is_locked': bool(getattr(s, 'is_locked', False)),
            'slot_minutes': int(getattr(s, 'slot_minutes', 10) or 10),
            'is_closed': bool(getattr(s, 'is_closed', False))
        })
    # Tạo đủ 15 ngày (mỗi phần tử một ngày, kể cả ngày chưa có ca trong DB)
    for i in range(15):
        d = today + timedelta(days=i)
        d_str = d.strftime('%Y-%m-%d')
        days.append({
            'date': d_str,
            'shifts': schedule_dict.get(d_str, [])
        })
    return jsonify(days)

@app.route('/api/admin/work-schedule', methods=['GET'])
def admin_get_work_schedule():
    ensure_work_schedule_columns()
    # Lấy lịch làm việc theo ngày (có thể truyền ?date=yyyy-mm-dd)
    date = request.args.get('date')
    start_date = request.args.get('start_date')
    end_date = request.args.get('end_date')

    q = WorkSchedule.query
    if start_date and end_date:
        try:
            sd = datetime.strptime(start_date, '%Y-%m-%d').date().strftime('%Y-%m-%d')
            ed = datetime.strptime(end_date, '%Y-%m-%d').date().strftime('%Y-%m-%d')
            q = q.filter(WorkSchedule.date >= sd, WorkSchedule.date <= ed)
        except Exception:
            # fallback về mode theo 'date' nếu start/end sai định dạng
            if date:
                q = q.filter_by(date=date)
    elif date:
        q = q.filter_by(date=date)
    schedules = q.order_by(WorkSchedule.date, WorkSchedule.start_time).all()
    return jsonify([
        {
            'id': s.id,
            'external_id': (getattr(s, 'external_id', None) or ''),
            'date': s.date,
            'start_time': s.start_time,
            'end_time': s.end_time,
            'doctor_name': s.doctor_name,
            'is_locked': bool(getattr(s, 'is_locked', False)),
            'slot_minutes': int(getattr(s, 'slot_minutes', 10) or 10),
            'is_closed': bool(getattr(s, 'is_closed', False))
        } for s in schedules
    ])

@app.route('/api/admin/work-schedule', methods=['POST'])
def admin_add_work_schedule():
    ensure_work_schedule_columns()
    is_mirrored_request = (request.headers.get('X-Work-Schedule-Mirror') or '').strip() == '1'
    data = request.json or {}
    external_id = (data.get('external_id') or '').strip() or str(uuid.uuid4())
    exists = WorkSchedule.query.filter_by(external_id=external_id).first()
    if exists:
        exists.date = data.get('date', exists.date)
        exists.start_time = data.get('start_time', exists.start_time)
        exists.end_time = data.get('end_time', exists.end_time)
        exists.doctor_name = data.get('doctor_name', exists.doctor_name)
        exists.is_locked = bool(data.get('is_locked', exists.is_locked))
        try:
            exists.slot_minutes = int(data.get('slot_minutes', exists.slot_minutes or 10) or 10)
        except Exception:
            pass
        exists.is_closed = bool(data.get('is_closed', exists.is_closed))
        db.session.commit()
        payload = _work_schedule_payload(exists)
        if not is_mirrored_request:
            _mirror_work_schedule_upsert_to_peer(payload)
            _emit_sync_event('work_schedule', external_id, 'work_schedule.upsert', {'work_schedule': payload})
        return jsonify({'message': 'Đã thêm ca khám!', 'id': exists.id, 'external_id': external_id})

    ws = WorkSchedule(
        external_id=external_id,
        date=data['date'],
        start_time=data['start_time'],
        end_time=data['end_time'],
        doctor_name=data['doctor_name'],
        is_locked=bool(data.get('is_locked', False)),
        slot_minutes=int(data.get('slot_minutes', 10)),
        is_closed=bool(data.get('is_closed', False))
    )
    db.session.add(ws)
    db.session.commit()
    payload = _work_schedule_payload(ws)
    if not is_mirrored_request:
        _mirror_work_schedule_upsert_to_peer(payload)
        _emit_sync_event('work_schedule', external_id, 'work_schedule.upsert', {'work_schedule': payload})
    return jsonify({'message': 'Đã thêm ca khám!', 'id': ws.id, 'external_id': external_id})

@app.route('/api/admin/work-schedule/<int:id>', methods=['PUT'])
def admin_update_work_schedule(id):
    ensure_work_schedule_columns()
    is_mirrored_request = (request.headers.get('X-Work-Schedule-Mirror') or '').strip() == '1'
    ws = _get_or_404(WorkSchedule, id)
    if not ws.external_id:
        ws.external_id = str(uuid.uuid4())
    data = request.json
    ws.date = data.get('date', ws.date)
    ws.start_time = data.get('start_time', ws.start_time)
    ws.end_time = data.get('end_time', ws.end_time)
    ws.doctor_name = data.get('doctor_name', ws.doctor_name)
    if 'is_locked' in data:
        ws.is_locked = bool(data.get('is_locked'))
    if 'slot_minutes' in data:
        try:
            ws.slot_minutes = int(data.get('slot_minutes') or 10)
        except Exception:
            pass
    if 'is_closed' in data:
        ws.is_closed = bool(data.get('is_closed'))
    db.session.commit()
    payload = _work_schedule_payload(ws)
    if not is_mirrored_request:
        _mirror_work_schedule_upsert_to_peer(payload)
        _emit_sync_event('work_schedule', ws.external_id, 'work_schedule.upsert', {'work_schedule': payload})
    return jsonify({'message': 'Đã cập nhật ca khám!'})

@app.route('/api/admin/work-schedule/<int:id>', methods=['DELETE'])
def admin_delete_work_schedule(id):
    is_mirrored_request = (request.headers.get('X-Work-Schedule-Mirror') or '').strip() == '1'
    ws = _get_or_404(WorkSchedule, id)
    external_id = (ws.external_id or '').strip() or str(uuid.uuid4())
    ws.external_id = external_id
    db.session.delete(ws)
    db.session.commit()
    if not is_mirrored_request:
        _mirror_work_schedule_delete_to_peer(external_id)
        _emit_sync_event('work_schedule', external_id, 'work_schedule.deleted', {'work_schedule': {'external_id': external_id}})
    return jsonify({'message': 'Đã xóa ca khám!'})

@app.route('/api/admin/work-schedule/by-external-id/<string:external_id>', methods=['PUT', 'DELETE'])
def admin_work_schedule_by_external_id(external_id: str):
    ensure_work_schedule_columns()
    ext_id = (external_id or '').strip()
    if not ext_id:
        return jsonify({'message': 'Thiếu external_id'}), 400
    if request.method == 'DELETE':
        ws = WorkSchedule.query.filter_by(external_id=ext_id).first()
        if not ws:
            return jsonify({'message': 'Không tìm thấy ca khám theo external_id'}), 404
        return admin_delete_work_schedule(ws.id)

    data = request.json or {}
    ws = WorkSchedule.query.filter_by(external_id=ext_id).first()
    if not ws:
        ws = WorkSchedule(
            external_id=ext_id,
            date=data.get('date') or datetime.now().strftime('%Y-%m-%d'),
            start_time=data.get('start_time') or '00:00',
            end_time=data.get('end_time') or '00:00',
            doctor_name=data.get('doctor_name') or 'PK Đại Anh',
            is_locked=bool(data.get('is_locked', False)),
            slot_minutes=int(data.get('slot_minutes', 10) or 10),
            is_closed=bool(data.get('is_closed', False)),
        )
        db.session.add(ws)
        db.session.commit()
        return jsonify({'message': 'Đã thêm ca khám!', 'id': ws.id, 'external_id': ext_id})
    return admin_update_work_schedule(ws.id)

STAFF_HOURLY_RATE_KEY = 'staff_hourly_rate'
STAFF_MEMBER_USER_IDS_KEY = 'staff_member_user_ids'


def _staff_member_candidates():
    """Danh sách user có thể dùng cho lịch/chấm công nhân viên."""
    users = User.query.order_by(User.full_name.asc(), User.username.asc()).all()
    out = []
    for u in users:
        roles = [r.name.lower() for r in (u.roles or [])]
        if u.status != 'active':
            continue
        # Không đưa tài khoản chỉ có quyền admin vào danh sách nhân viên phụ khám.
        if roles and all(r == 'admin' for r in roles):
            continue
        out.append({
            'id': int(u.id),
            'username': u.username,
            'full_name': u.full_name,
            'roles': roles,
            'status': u.status,
        })
    return out


def _staff_member_selected_ids(candidates=None):
    candidates = candidates if candidates is not None else _staff_member_candidates()
    candidate_ids = {int(x['id']) for x in candidates}
    raw = AppSetting.get_value(STAFF_MEMBER_USER_IDS_KEY, '') or ''
    selected = []
    if raw:
        try:
            parsed = json.loads(raw)
            if isinstance(parsed, list):
                for x in parsed:
                    try:
                        val = int(x)
                    except Exception:
                        continue
                    if val in candidate_ids:
                        selected.append(val)
        except Exception:
            selected = []
    # Mặc định: nếu chưa cấu hình thì lấy tất cả candidate active.
    if not selected:
        selected = sorted(candidate_ids)
    return sorted(set(selected))


@app.route('/api/staff-members', methods=['GET'])
def api_get_staff_members():
    """
    Trả về danh sách nhân viên dùng cho lịch/chấm công.
    GET cho phép người dùng đã đăng nhập xem để tự chấm công.
    """
    candidates = _staff_member_candidates()
    selected_ids = set(_staff_member_selected_ids(candidates))
    selected = [x for x in candidates if int(x['id']) in selected_ids]
    return jsonify({
        'selected': selected,
        'all_candidates': candidates,
        'selected_ids': sorted(selected_ids),
    })


@app.route('/api/staff-members', methods=['POST'])
def api_set_staff_members():
    """Lưu danh sách nhân viên từ users.html (yêu cầu manage_users)."""
    auth_header = request.headers.get('Authorization', '')
    token = auth_header.split(' ', 1)[1] if auth_header.startswith('Bearer ') else auth_header
    user_id = get_user_from_token(token)
    if not user_id or not has_permission(user_id, 'manage_users'):
        return jsonify({'error': 'Forbidden'}), 403

    payload = request.get_json(silent=True) or {}
    raw_ids = payload.get('user_ids', [])
    if not isinstance(raw_ids, list):
        return jsonify({'error': 'user_ids phải là mảng'}), 400

    candidates = _staff_member_candidates()
    candidate_ids = {int(x['id']) for x in candidates}
    selected = []
    for x in raw_ids:
        try:
            val = int(x)
        except Exception:
            continue
        if val in candidate_ids:
            selected.append(val)
    selected = sorted(set(selected))

    AppSetting.set_value(STAFF_MEMBER_USER_IDS_KEY, json.dumps(selected, ensure_ascii=False))
    selected_users = [x for x in candidates if int(x['id']) in set(selected)]
    return jsonify({
        'message': 'Đã cập nhật danh sách nhân viên phụ khám',
        'selected_ids': selected,
        'selected': selected_users,
    })

DOCTOR_HOSPITAL_SCHEDULES_KEY = 'doctor_hospital_schedules'
DOCTOR_HOSPITAL_SCHEDULES_MEDIA_DIR = os.path.join(
    os.path.dirname(os.path.abspath(__file__)), 'doctor-hospital-schedules-media'
)
try:
    os.makedirs(DOCTOR_HOSPITAL_SCHEDULES_MEDIA_DIR, exist_ok=True)
except Exception:
    pass
DOCTOR_HOSPITAL_SCHEDULES_ALLOWED_EXTS = {'.jpg', '.jpeg', '.png', '.webp', '.gif'}
DOCTOR_HOSPITAL_SCHEDULE_KEYS = ('bs_dai', 'bs_quynh_anh')


def _doctor_hospital_schedules_public_url(filename: str) -> str:
    return f"/doctor-hospital-schedules-media/{filename}"


def _default_doctor_hospital_schedules():
    return {
        'bs_dai': {
            'label': 'Bác sĩ Đại',
            'notes': '',
            'images': [],
        },
        'bs_quynh_anh': {
            'label': 'Bác sĩ Quỳnh Anh',
            'notes': '',
            'images': [],
        },
    }


def _load_doctor_hospital_schedules():
    raw = AppSetting.get_value(DOCTOR_HOSPITAL_SCHEDULES_KEY, '') or ''
    data = {}
    try:
        parsed = json.loads(raw) if raw else {}
        if isinstance(parsed, dict):
            data = parsed
    except Exception:
        data = {}
    base = _default_doctor_hospital_schedules()
    for key in DOCTOR_HOSPITAL_SCHEDULE_KEYS:
        item = data.get(key) if isinstance(data.get(key), dict) else {}
        images = item.get('images') if isinstance(item.get('images'), list) else []
        clean_images = []
        for img in images:
            if not isinstance(img, dict):
                continue
            fn = str(img.get('filename') or '').strip()
            if not fn or '/' in fn or '..' in fn:
                continue
            safe = werkzeug.utils.secure_filename(os.path.basename(fn))
            if not safe:
                continue
            clean_images.append({
                'filename': safe,
                'url': img.get('url') or _doctor_hospital_schedules_public_url(safe),
                'caption': str(img.get('caption') or ''),
                'uploaded_at': img.get('uploaded_at'),
            })
        base[key]['notes'] = str(item.get('notes') or '')
        base[key]['images'] = clean_images
        if item.get('label'):
            base[key]['label'] = str(item.get('label'))
    return base


def _save_doctor_hospital_schedules(payload: dict):
    AppSetting.set_value(DOCTOR_HOSPITAL_SCHEDULES_KEY, json.dumps(payload, ensure_ascii=False))


@app.route('/doctor-hospital-schedules-media/<path:filename>')
def doctor_hospital_schedules_media_file(filename):
    safe = werkzeug.utils.secure_filename(os.path.basename(str(filename).replace('\\', '/')))
    if not safe:
        abort(404)
    path = os.path.join(DOCTOR_HOSPITAL_SCHEDULES_MEDIA_DIR, safe)
    if not os.path.isfile(path):
        abort(404)
    return send_file(path, conditional=True)


@app.route('/api/doctor-hospital-schedules', methods=['GET'])
def api_get_doctor_hospital_schedules():
    try:
        return jsonify({'success': True, 'schedules': _load_doctor_hospital_schedules()})
    except Exception as e:
        return jsonify({'success': False, 'error': str(e)}), 500


@app.route('/api/doctor-hospital-schedules/notes', methods=['POST'])
def api_set_doctor_hospital_schedule_notes():
    try:
        data = request.get_json(silent=True) or {}
        doctor_key = str(data.get('doctor_key') or '').strip()
        if doctor_key not in DOCTOR_HOSPITAL_SCHEDULE_KEYS:
            return jsonify({'success': False, 'error': 'doctor_key không hợp lệ'}), 400
        schedules = _load_doctor_hospital_schedules()
        schedules[doctor_key]['notes'] = str(data.get('notes') or '')
        _save_doctor_hospital_schedules(schedules)
        return jsonify({'success': True, 'schedules': schedules})
    except Exception as e:
        return jsonify({'success': False, 'error': str(e)}), 500


@app.route('/api/doctor-hospital-schedules/upload', methods=['POST'])
@require_auth
def api_upload_doctor_hospital_schedule_image(**kwargs):
    try:
        doctor_key = str(request.form.get('doctor_key') or '').strip()
        if doctor_key not in DOCTOR_HOSPITAL_SCHEDULE_KEYS:
            return jsonify({'success': False, 'error': 'doctor_key không hợp lệ'}), 400
        files = request.files.getlist('files') or []
        if not files:
            one = request.files.get('file') or request.files.get('image')
            if one:
                files = [one]
        if not files:
            return jsonify({'success': False, 'error': 'Thiếu file ảnh'}), 400

        caption = str(request.form.get('caption') or '').strip()
        schedules = _load_doctor_hospital_schedules()
        saved = []
        for f in files:
            if not f or not getattr(f, 'filename', ''):
                continue
            original = str(f.filename)
            filename = werkzeug.utils.secure_filename(original)
            if not filename:
                continue
            ext = os.path.splitext(filename)[1].lower()
            if ext not in DOCTOR_HOSPITAL_SCHEDULES_ALLOWED_EXTS:
                return jsonify({'success': False, 'error': f'File không hỗ trợ: {original}'}), 400
            base = os.path.splitext(filename)[0]
            final_name = f"{doctor_key}_{base}{ext}"
            i = 1
            dst = os.path.join(DOCTOR_HOSPITAL_SCHEDULES_MEDIA_DIR, final_name)
            while os.path.exists(dst):
                final_name = f"{doctor_key}_{base}-{i}{ext}"
                dst = os.path.join(DOCTOR_HOSPITAL_SCHEDULES_MEDIA_DIR, final_name)
                i += 1
            f.save(dst)
            entry = {
                'filename': final_name,
                'url': _doctor_hospital_schedules_public_url(final_name),
                'caption': caption,
                'uploaded_at': datetime.utcnow().isoformat() + 'Z',
            }
            schedules[doctor_key]['images'].append(entry)
            saved.append(entry)

        if not saved:
            return jsonify({'success': False, 'error': 'Không có ảnh hợp lệ'}), 400
        _save_doctor_hospital_schedules(schedules)
        return jsonify({'success': True, 'files': saved, 'schedules': schedules})
    except Exception as e:
        return jsonify({'success': False, 'error': str(e)}), 500


@app.route('/api/doctor-hospital-schedules/delete-image', methods=['POST'])
@require_auth
def api_delete_doctor_hospital_schedule_image(**kwargs):
    try:
        data = request.get_json(silent=True) or {}
        doctor_key = str(data.get('doctor_key') or '').strip()
        filename = str(data.get('filename') or '').strip()
        if doctor_key not in DOCTOR_HOSPITAL_SCHEDULE_KEYS:
            return jsonify({'success': False, 'error': 'doctor_key không hợp lệ'}), 400
        if not filename or '/' in filename or '..' in filename:
            return jsonify({'success': False, 'error': 'Tên file không hợp lệ'}), 400
        safe = werkzeug.utils.secure_filename(os.path.basename(filename))
        if not safe:
            return jsonify({'success': False, 'error': 'Tên file không hợp lệ'}), 400

        schedules = _load_doctor_hospital_schedules()
        before = len(schedules[doctor_key]['images'])
        schedules[doctor_key]['images'] = [
            img for img in schedules[doctor_key]['images'] if img.get('filename') != safe
        ]
        path = os.path.join(DOCTOR_HOSPITAL_SCHEDULES_MEDIA_DIR, safe)
        if os.path.isfile(path):
            os.remove(path)
        if len(schedules[doctor_key]['images']) == before and not os.path.isfile(path):
            # still save in case metadata was stale
            pass
        _save_doctor_hospital_schedules(schedules)
        return jsonify({'success': True, 'schedules': schedules})
    except Exception as e:
        return jsonify({'success': False, 'error': str(e)}), 500


