@app.route('/api/mwl-sync', methods=['POST'])
@require_permission('manage_worklist')
def api_trigger_mwl_sync():
    try:
        # Trigger immediate sync: run mwl_sync logic inline
        import mwl_sync
        entries = mwl_sync.build_worklist_entries()
        mwl_store.init_db()
        _cleanup_outdated_mwl_entries()
        old_entries = mwl_store.get_all_entries()
        old_by_acc = {
            (x.get('AccessionNumber') or ''): x
            for x in old_entries
            if (x.get('AccessionNumber') or '')
        }

        new_by_acc = {
            (x.get('AccessionNumber') or ''): x
            for x in entries
            if (x.get('AccessionNumber') or '')
        }

        added = 0
        updated = 0
        unchanged = 0
        removed = 0

        for acc, row in new_by_acc.items():
            old_row = old_by_acc.get(acc)
            if not old_row:
                added += 1
                continue
            if _mwl_entry_compare_tuple(old_row) == _mwl_entry_compare_tuple(row):
                unchanged += 1
            else:
                updated += 1

        for acc in old_by_acc.keys():
            if acc not in new_by_acc:
                removed += 1

        mwl_store.clear_all()
        for e in entries:
            mwl_store.upsert_entry(e)
        _touch_mwl_reload_signal()
        return jsonify({
            'success': True,
            'imported': len(entries),
            'added': added,
            'updated': updated,
            'unchanged': unchanged,
            'removed': removed,
            'total_after_sync': len(entries),
            'total_before_sync': len(old_entries),
            'days_ahead': _mwl_sync_days_ahead(),
        })
    except Exception as e:
        return jsonify({'success': False, 'error': str(e)}), 500

@app.route('/api/checkin/stats', methods=['GET'])
def checkin_stats():
    try:
        today = datetime.utcnow().date()
        
        # Tổng số check-in hôm nay
        total_checkins = CheckIn.query.filter_by(checkin_date=today).count()
        
        # Số thứ tự đang khám hiện tại (status=serving)
        serving_checkin = (
            CheckIn.query
            .filter_by(checkin_date=today, status='serving')
            .order_by(CheckIn.queue_number.desc())
            .first()
        )
        current_queue = serving_checkin.queue_number if serving_checkin else 0
        
        # Số bệnh nhân đang chờ
        waiting_count = CheckIn.query.filter_by(checkin_date=today, status='waiting').count()
        
        return jsonify({
            'total_checkins': total_checkins,
            'current_queue': current_queue,
            'waiting_count': waiting_count
        })
        
    except Exception as e:
        return jsonify({'error': str(e)}), 500

@app.route('/api/checkin/waiting-list', methods=['GET'])
def waiting_list():
    try:
        today = datetime.utcnow().date()

        include_cancelled = request.args.get('include_cancelled') == '1'
        q = CheckIn.query.filter_by(checkin_date=today)
        if not include_cancelled:
            q = q.filter(CheckIn.status != 'cancelled')
        status_filter = (request.args.get('status') or '').strip()
        if status_filter:
            q = q.filter(CheckIn.status == status_filter)
        checkins = q.order_by(CheckIn.queue_number.asc()).all()
        
        waiting_list = []
        for checkin in checkins:
            waiting_list.append({
                'id': checkin.id,
                'queue_number': checkin.queue_number,
                'name': checkin.name or 'Khách hàng',
                'phone': checkin.phone or 'Chưa có',
                'checkin_time': checkin.checkin_time.isoformat(),
                'status': checkin.status
            })
        
        return jsonify(waiting_list)
        
    except Exception as e:
        return jsonify({'error': str(e)}), 500

