@app.route('/api/role-permissions', methods=['GET'])
@require_permission('system_config')
def api_get_role_permissions(*args, **kwargs):
    try:
        ensure_role_permission_table()
        rows = db.session.execute(
            text("SELECT role_name, permission_key FROM role_permission")
        ).fetchall()
        mapping = {}
        for role_name, perm in rows:
            mapping.setdefault(role_name, []).append(perm)
        return jsonify(mapping)
    except Exception as e:
        return jsonify({'error': str(e)}), 500

@app.route('/api/role-permissions', methods=['PUT'])
@require_permission('system_config')
def api_put_role_permissions(*args, **kwargs):
    try:
        ensure_role_permission_table()
        data = request.json or {}
        # Replace all
        db.session.execute(text('DELETE FROM role_permission'))
        for role_name, perms in data.items():
            if not isinstance(perms, list):
                continue
            for perm in perms:
                db.session.add(RolePermission(role_name=role_name, permission_key=perm))
        db.session.commit()
        return jsonify({'success': True})
    except Exception as e:
        db.session.rollback()
        return jsonify({'error': str(e)}), 500

# API endpoint để reset mật khẩu (tùy chọn)
@app.route('/api/forgot-password', methods=['POST'])
@rate_limit('forgot')
def forgot_password():
    """API để gửi email reset mật khẩu"""
    try:
        data = request.json
        username = data.get('username')
        email = data.get('email')
        
        if not username or not email:
            return jsonify({'error': 'Vui lòng cung cấp tên đăng nhập và email'}), 400
        
        # Kiểm tra user có tồn tại không
        result = db.session.execute(
            text("SELECT id, username, full_name, email FROM user WHERE username = :username AND email = :email"),
            {"username": username, "email": email}
        ).fetchone()
        
        if not result:
            return jsonify({'error': 'Không tìm thấy tài khoản với thông tin đã cung cấp'}), 404
        
        user_id, username_db, full_name, user_email = result
        
        # Tạo mật khẩu mới ngẫu nhiên, tuân thủ chính sách mạnh
        import secrets
        import string
        charset_upper = string.ascii_uppercase
        charset_lower = string.ascii_lowercase
        charset_digits = string.digits
        charset_special = '!@#$%^&*()-_=+[]{};:,.?'
        # Đảm bảo có đủ các loại ký tự
        base = [
            secrets.choice(charset_upper),
            secrets.choice(charset_lower),
            secrets.choice(charset_digits),
            secrets.choice(charset_special),
        ]
        remaining_len = max(PASSWORD_MIN_LENGTH, 8) - len(base)
        all_chars = charset_upper + charset_lower + charset_digits + charset_special
        base.extend(secrets.choice(all_chars) for _ in range(remaining_len))
        secrets.SystemRandom().shuffle(base)
        new_password = ''.join(base)
        
        # Cập nhật mật khẩu mới
        password_hash = hash_password(new_password)
        db.session.execute(
            text("UPDATE user SET password_hash = :password_hash, must_change_password = 1, password_changed_at = NULL WHERE id = :user_id"),
            {"password_hash": password_hash, "user_id": user_id}
        )
        db.session.commit()
        
        # Gửi email (mô phỏng - trong thực tế cần tích hợp SMTP)
        print(f"=== EMAIL RESET PASSWORD ===")
        print(f"To: {user_email}")
        print(f"Subject: Reset mật khẩu - Phòng khám Đại Anh")
        print(f"Body:")
        print(f"Xin chào {full_name},")
        print(f"Tài khoản của bạn đã được reset mật khẩu.")
        print(f"Tên đăng nhập: {username_db}")
        print(f"Mật khẩu mới: {new_password}")
        print(f"Vui lòng đăng nhập và thay đổi mật khẩu ngay.")
        print(f"==========================")
        
        out = {'message': 'Mật khẩu đã được reset. Vui lòng đăng nhập và đổi mật khẩu ngay.'}
        # Trả mật khẩu mới khi: DEBUG hoặc email recovery chính thức (admin)
        if app.config.get('DEBUG') or (user_email and user_email.strip().lower() == 'phusandaianh@gmail.com'):
            out['new_password'] = new_password
        return jsonify(out)
        
    except Exception as e:
        print(f"Forgot password error: {e}")
        return jsonify({'error': 'Lỗi hệ thống'}), 500

@app.route('/api/generate-clinical-form-pdf', methods=['POST'])
def generate_clinical_form_pdf():
    """Generate PDF for clinical form"""
    try:
        data = request.json
        content = data.get('content', '')
        filename = data.get('filename', 'clinical_form.pdf')
        
        # Create PDF buffer
        buffer = BytesIO()
        doc = SimpleDocTemplate(buffer, pagesize=A4, topMargin=0.5*inch, bottomMargin=0.5*inch)
        
        # Parse HTML content and convert to PDF elements
        from reportlab.platypus import Paragraph, Spacer
        from reportlab.lib.styles import getSampleStyleSheet
        from reportlab.lib.enums import TA_CENTER, TA_LEFT
        
        styles = getSampleStyleSheet()
        story = []

        # Register Unicode font for Vietnamese text (Windows local server)
        base_font = 'Helvetica'
        bold_font = 'Helvetica-Bold'
        try:
            arial_path = os.path.join(os.environ.get('WINDIR', 'C:\\Windows'), 'Fonts', 'arial.ttf')
            arial_bold_path = os.path.join(os.environ.get('WINDIR', 'C:\\Windows'), 'Fonts', 'arialbd.ttf')
            if os.path.exists(arial_path):
                pdfmetrics.registerFont(TTFont('ArialUnicode', arial_path))
                base_font = 'ArialUnicode'
            if os.path.exists(arial_bold_path):
                pdfmetrics.registerFont(TTFont('ArialUnicodeBold', arial_bold_path))
                bold_font = 'ArialUnicodeBold'
            elif base_font == 'ArialUnicode':
                bold_font = 'ArialUnicode'
        except Exception as font_error:
            print(f"PDF font fallback to Helvetica: {font_error}")
        
        # Create custom styles
        title_style = styles['Heading1']
        title_style.alignment = TA_CENTER
        title_style.fontSize = 16
        title_style.textColor = colors.blue
        title_style.fontName = bold_font
        
        normal_style = styles['Normal']
        normal_style.fontSize = 10
        normal_style.fontName = base_font
        
        # Process HTML content
        # Split content into lines and process each
        lines = content.split('\n')
        for line in lines:
            line = line.strip()
            if not line:
                story.append(Spacer(1, 6))
                continue
                
            # Handle different HTML elements
            if '<h2' in line and 'PHIẾU CHỈ ĐỊNH CẬN LÂM SÀNG' in line:
                # Extract title text
                title_text = re.sub(r'<[^>]+>', '', line)
                para = Paragraph(title_text, title_style)
                story.append(para)
                story.append(Spacer(1, 12))
            elif '<table' in line or '<tr' in line or '<td' in line:
                # Handle table content - convert to simple text
                text_content = re.sub(r'<[^>]+>', ' ', line)
                text_content = re.sub(r'\s+', ' ', text_content).strip()
                if text_content:
                    para = Paragraph(text_content, normal_style)
                    story.append(para)
            elif '<strong>' in line or '<b>' in line:
                # Bold text
                text_content = re.sub(r'<[^>]+>', '', line)
                bold_style = styles['BodyText']
                bold_style.fontSize = 10
                bold_style.fontName = 'Helvetica-Bold'
                bold_style.fontName = bold_font
                para = Paragraph(text_content, bold_style)
                story.append(para)
            else:
                # Regular text
                text_content = re.sub(r'<[^>]+>', '', line)
                if text_content.strip():
                    para = Paragraph(text_content, normal_style)
                    story.append(para)
        
        # Build PDF
        doc.build(story)
        
        # Get PDF data
        pdf_data = buffer.getvalue()
        buffer.close()
        
        # Return PDF as response
        response = app.response_class(
            pdf_data,
            mimetype='application/pdf',
            headers={'Content-Disposition': f'attachment; filename="{filename}"'}
        )
        return response
        
    except Exception as e:
        print(f"Error generating PDF: {e}")
        return jsonify({'error': str(e)}), 500

# Pricing Files API
@app.route('/api/upload-pricing', methods=['POST'])
@app.route('/api/upload-pricing-file', methods=['POST'])
def upload_pricing_file():
    """Upload pricing file (PDF) to server and database."""
    try:
        file = request.files.get('pricing_file') or request.files.get('file')
        if not file:
            return jsonify({'success': False, 'message': 'Không có file được chọn'}), 400
        
        file_type = request.form.get('file_type', 'nipt_pricing')
        
        if not file.filename:
            return jsonify({'success': False, 'message': 'Không có file được chọn'}), 400
        
        if not file.filename.lower().endswith('.pdf'):
            return jsonify({'success': False, 'message': 'Chỉ được upload file PDF'}), 400
        
        # Create uploads directory if not exists
        upload_dir = os.path.join(app.root_path, 'uploads', 'pricing')
        os.makedirs(upload_dir, exist_ok=True)
        
        # Sanitize filename (giữ đuôi .pdf, bỏ ký tự path nguy hiểm)
        original_name = os.path.basename(file.filename).replace('\x00', '')
        safe_base = re.sub(r'[<>:"/\\|?*]+', '_', original_name).strip(' .') or 'document.pdf'
        if not safe_base.lower().endswith('.pdf'):
            safe_base += '.pdf'
        timestamp = datetime.now().strftime('%Y%m%d_%H%M%S')
        unique_filename = f"{file_type}_{timestamp}_{safe_base}"
        file_path = os.path.join(upload_dir, unique_filename)
        
        # Save file
        file.save(file_path)
        
        # Get file info
        file_size = os.path.getsize(file_path)
        
        # Delete old file of same type if exists
        old_file = PricingFile.query.filter_by(file_type=file_type).first()
        if old_file:
            try:
                old_path = old_file.file_path
                if old_path and not os.path.isabs(old_path):
                    old_path = os.path.join(app.root_path, old_path)
                if old_path and os.path.exists(old_path):
                    os.remove(old_path)
            except Exception:
                pass
            db.session.delete(old_file)
        
        # Store relative path for portability
        relative_path = os.path.join('uploads', 'pricing', unique_filename)

        # Save to database
        pricing_file = PricingFile(
            file_type=file_type,
            filename=unique_filename,
            original_filename=original_name,
            file_path=relative_path,
            file_size=file_size,
            mime_type=file.content_type or 'application/pdf'
        )
        
        db.session.add(pricing_file)
        db.session.commit()
        
        return jsonify({
            'success': True,
            'message': 'Upload thành công',
            'file': pricing_file.to_dict()
        })
        
    except Exception as e:
        db.session.rollback()
        print(f"Upload error: {e}")
        return jsonify({'success': False, 'message': f'Lỗi upload: {str(e)}'}), 500

@app.route('/api/get-pricing-file', methods=['GET'])
def get_pricing_file():
    """Get pricing file from database."""
    try:
        file_type = request.args.get('type', 'nipt_pricing')
        download = request.args.get('download', 'false').lower() == 'true'
        info_only = request.args.get('info', 'false').lower() == 'true'
        
        pricing_file = PricingFile.query.filter_by(file_type=file_type).first()
        
        if not pricing_file:
            return jsonify({'success': False, 'message': 'Không tìm thấy file'}), 404
        
        if info_only:
            # Return file info only
            return jsonify({
                'success': True,
                'file': pricing_file.to_dict()
            })
        elif download:
            # Return file for download
            # Normalize file path
            file_path = pricing_file.file_path
            if not os.path.isabs(file_path):
                file_path = os.path.join(app.root_path, file_path)
            file_path = os.path.normpath(file_path)
            
            # Check if file exists, try alternative paths if not
            if not os.path.exists(file_path):
                alt_paths = [
                    pricing_file.file_path,
                    os.path.join(app.root_path, pricing_file.file_path),
                    os.path.join('uploads', 'pricing', os.path.basename(pricing_file.file_path)),
                ]
                
                for alt_path in alt_paths:
                    alt_path = os.path.normpath(alt_path)
                    if os.path.exists(alt_path):
                        file_path = alt_path
                        break
                else:
                    return jsonify({'success': False, 'message': f'File không tồn tại tại đường dẫn: {pricing_file.file_path}'}), 404
            
            return send_file(
                file_path,
                as_attachment=True,
                download_name=re.sub(r'[^\x20-\x7E]', '_', pricing_file.original_filename or 'document.pdf') or 'document.pdf',
                mimetype=pricing_file.mime_type or 'application/pdf'
            )
        else:
            # Return file for viewing (inline)
            # Normalize file path - handle both absolute and relative paths
            file_path = pricing_file.file_path
            if not os.path.isabs(file_path):
                # If relative path, make it relative to app root
                file_path = os.path.join(app.root_path, file_path)
            
            # Normalize the path (handle .. and .)
            file_path = os.path.normpath(file_path)
            
            # Check if file exists, try alternative paths if not
            if not os.path.exists(file_path):
                alt_paths = [
                    pricing_file.file_path,  # Original path
                    os.path.join(app.root_path, pricing_file.file_path),  # Relative to app root
                    os.path.join('uploads', 'pricing', os.path.basename(pricing_file.file_path)),  # Just filename
                ]
                
                for alt_path in alt_paths:
                    alt_path = os.path.normpath(alt_path)
                    if os.path.exists(alt_path):
                        file_path = alt_path
                        break
                else:
                    return jsonify({'success': False, 'message': f'File không tồn tại tại đường dẫn: {pricing_file.file_path}'}), 404
            
            # Add headers to allow iframe embedding (ASCII-only in filename=)
            from urllib.parse import quote
            original = pricing_file.original_filename or 'document.pdf'
            ascii_name = re.sub(r'[^\x20-\x7E]', '_', original).replace('"', '') or 'document.pdf'
            utf8_name = quote(original, safe='')
            
            response = send_file(
                file_path,
                as_attachment=False,
                download_name=ascii_name,
                mimetype=pricing_file.mime_type or 'application/pdf'
            )
            response.headers['Content-Disposition'] = (
                f'inline; filename="{ascii_name}"; filename*=UTF-8\'\'{utf8_name}'
            )
            response.headers['X-Content-Type-Options'] = 'nosniff'
            response.headers['Cache-Control'] = 'public, max-age=3600'
            return response
            
    except Exception as e:
        print(f"Get pricing file error: {e}")
        return jsonify({'success': False, 'message': f'Lỗi: {str(e)}'}), 500

