@app.route('/api/vr-pacs/patients', methods=['GET'])
@_require_staff_api_access
def vr_pacs_get_patients():
    """API để lấy danh sách bệnh nhân và ảnh DICOM của họ"""
    try:
        from pathlib import Path
        import pydicom
        from datetime import datetime
        
        BASE_DIR = Path("received_dicoms")
        if not BASE_DIR.exists():
            BASE_DIR.mkdir(exist_ok=True)
        
        patients = []
        total_images = 0
        total_studies = 0
        
        # Scan all patient folders
        for patient_dir in sorted(BASE_DIR.iterdir()):
            if not patient_dir.is_dir():
                continue
            
            patient_name = patient_dir.name
            dicom_files = []
            latest_date = None
            dicom_patient_id = ''
            dicom_patient_name = ''
            
            # Get all DICOM files in patient folder
            for dicom_file in sorted(patient_dir.glob("*.dcm")):
                try:
                    # Try to read DICOM metadata
                    ds = pydicom.dcmread(dicom_file, stop_before_pixels=True)
                    study_date = ds.get("StudyDate", "")
                    if not dicom_patient_id:
                        dicom_patient_id = str(ds.get("PatientID", "") or '').strip()
                    if not dicom_patient_name:
                        dicom_patient_name = str(ds.get("PatientName", "") or '').strip()
                    if study_date and (not latest_date or study_date > latest_date):
                        latest_date = study_date
                    
                    dicom_files.append({
                        'filename': dicom_file.name,
                        'study_date': study_date,
                        'size': dicom_file.stat().st_size
                    })
                    total_images += 1
                except Exception as e:
                    # If can't read, still include the file
                    dicom_files.append({
                        'filename': dicom_file.name,
                        'study_date': '',
                        'size': dicom_file.stat().st_size
                    })
                    total_images += 1
            
            # Format date
            if latest_date and len(latest_date) == 8:
                try:
                    formatted_date = datetime.strptime(latest_date, "%Y%m%d").strftime("%d/%m/%Y")
                    latest_date = formatted_date
                except:
                    pass
            
            if dicom_files:
                patients.append({
                    'name': patient_name,
                    'patient_id': dicom_patient_id,
                    'patient_name_dicom': dicom_patient_name,
                    'display_name': dicom_patient_name or patient_name,
                    'images': dicom_files,
                    'latestDate': latest_date or '',
                    'image_count': len(dicom_files)
                })
                total_studies += 1
        
        return jsonify({
            'success': True,
            'patients': patients,
            'stats': {
                'totalPatients': len(patients),
                'totalImages': total_images,
                'totalStudies': total_studies
            }
        })
        
    except Exception as e:
        print(f"Error in vr_pacs_get_patients: {e}")
        import traceback
        traceback.print_exc()
        return jsonify({
            'success': False,
            'message': f'Lỗi khi tải dữ liệu: {str(e)}'
        }), 500

@app.route('/api/vr-pacs/preview/<path:patient_name>/<path:filename>', methods=['GET'])
@_require_staff_api_access
def vr_pacs_get_preview(patient_name, filename):
    """API để lấy ảnh preview (thumbnail) của DICOM"""
    try:
        from pathlib import Path
        import pydicom
        from PIL import Image
        import io

        dicom_path = _resolve_received_dicom_path(patient_name, filename)
        if not dicom_path:
            return jsonify({'error': 'File không tồn tại'}), 404

        # Read DICOM and convert to image
        ds = pydicom.dcmread(dicom_path)
        
        if hasattr(ds, "pixel_array"):
            img = Image.fromarray(ds.pixel_array)
            
            # Convert to RGB if needed
            if img.mode != 'RGB':
                img = img.convert('RGB')
            
            # Create thumbnail
            img.thumbnail((300, 300))
            
            # Convert to bytes
            buf = io.BytesIO()
            img.save(buf, format='PNG')
            buf.seek(0)
            
            return send_file(buf, mimetype='image/png')
        else:
            # Return placeholder image
            img = Image.new('RGB', (200, 200), color='#f0f0f0')
            buf = io.BytesIO()
            img.save(buf, format='PNG')
            buf.seek(0)
            return send_file(buf, mimetype='image/png')
            
    except Exception as e:
        print(f"Error in vr_pacs_get_preview: {e}")
        import traceback
        traceback.print_exc()
        # Return placeholder on error
        try:
            from PIL import Image
            import io
            img = Image.new('RGB', (200, 200), color='#f0f0f0')
            buf = io.BytesIO()
            img.save(buf, format='PNG')
            buf.seek(0)
            return send_file(buf, mimetype='image/png')
        except:
            return jsonify({'error': str(e)}), 500

@app.route('/api/vr-pacs/dicom/<path:patient_name>/<path:filename>', methods=['GET', 'OPTIONS'])
@_require_staff_api_access
def vr_pacs_get_dicom(patient_name, filename):
    """API để lấy file DICOM gốc để Cornerstone viewer hiển thị"""
    # Handle CORS preflight
    if request.method == 'OPTIONS':
        response = jsonify({'status': 'ok'})
        response.headers['Access-Control-Allow-Origin'] = '*'
        response.headers['Access-Control-Allow-Methods'] = 'GET, OPTIONS'
        response.headers['Access-Control-Allow-Headers'] = 'Content-Type, Authorization'
        return response
    try:
        dicom_path = _resolve_received_dicom_path(patient_name, filename)
        if not dicom_path:
            print(f"DICOM file not found or invalid path: {patient_name}/{filename}")
            return jsonify({'error': 'File DICOM không tồn tại'}), 404

        print(f"Serving DICOM file: {dicom_path}")
        
        # Return DICOM file with correct MIME type and CORS headers
        response = send_file(
            str(dicom_path),
            mimetype='application/dicom',
            as_attachment=False
        )
        
        # Add CORS headers for WADO URI loader
        response.headers['Access-Control-Allow-Origin'] = '*'
        response.headers['Access-Control-Allow-Methods'] = 'GET, OPTIONS'
        response.headers['Access-Control-Allow-Headers'] = 'Content-Type'
        
        return response
        
    except Exception as e:
        print(f"Error in vr_pacs_get_dicom: {e}")
        import traceback
        traceback.print_exc()
        return jsonify({'error': str(e)}), 500

def _get_orthanc_settings():
    """
    Read Orthanc endpoint/auth from env or local orthanc/orthanc.json.
    """
    base_url = (os.environ.get('ORTHANC_BASE_URL') or 'http://127.0.0.1:8042').strip().rstrip('/')
    username = os.environ.get('ORTHANC_USERNAME')
    password = os.environ.get('ORTHANC_PASSWORD')

    cfg_path = Path("orthanc/orthanc.json")
    if cfg_path.exists():
        try:
            cfg = json.loads(cfg_path.read_text(encoding='utf-8'))
            http_port = int(cfg.get('HttpPort', 8042) or 8042)
            base_url = (os.environ.get('ORTHANC_BASE_URL') or f"http://127.0.0.1:{http_port}").strip().rstrip('/')
            users = cfg.get('RegisteredUsers') or {}
            if isinstance(users, dict) and users and (not username or not password):
                first_user = next(iter(users.keys()))
                username = username or str(first_user)
                password = password or str(users[first_user])
        except Exception as e:
            print(f"Read orthanc config failed: {e}")

    if not username:
        username = 'admin'
    if password is None:
        password = 'orthanc123'
    return base_url, username, password

def _orthanc_find_study_id_by_uid(study_instance_uid: str):
    if not study_instance_uid:
        return None
    try:
        base_url, username, password = _get_orthanc_settings()
        url = f"{base_url}/tools/find"
        payload = json.dumps({
            "Level": "Study",
            "Expand": False,
            "Query": {
                "StudyInstanceUID": str(study_instance_uid)
            }
        }).encode('utf-8')
        req = urllib.request.Request(url, data=payload, method='POST')
        req.add_header('Content-Type', 'application/json')
        auth_raw = f"{username}:{password}".encode('utf-8')
        req.add_header('Authorization', 'Basic ' + base64.b64encode(auth_raw).decode('ascii'))
        with urllib.request.urlopen(req, timeout=4) as resp:
            body = resp.read().decode('utf-8', errors='ignore')
            data = json.loads(body) if body else []
            if isinstance(data, list) and data:
                return str(data[0])
    except Exception as e:
        print(f"Orthanc find study by UID failed: {e}")
    return None

def _orthanc_upload_dicom_file(dicom_path: Path) -> bool:
    """Upload one local DICOM file to Orthanc (/instances)."""
    try:
        if not dicom_path.exists() or not dicom_path.is_file():
            return False
        base_url, username, password = _get_orthanc_settings()
        req = urllib.request.Request(f"{base_url}/instances", data=dicom_path.read_bytes(), method='POST')
        req.add_header('Content-Type', 'application/dicom')
        auth_raw = f"{username}:{password}".encode('utf-8')
        req.add_header('Authorization', 'Basic ' + base64.b64encode(auth_raw).decode('ascii'))
        with urllib.request.urlopen(req, timeout=8) as resp:
            return int(getattr(resp, 'status', 200)) in (200, 201)
    except Exception as e:
        print(f"Orthanc upload failed for {dicom_path}: {e}")
        return False


@app.route('/api/pacs/orthanc-sync-file', methods=['POST'])
def pacs_orthanc_sync_file():
    """Upload một file DICOM local lên Orthanc (gọi từ dicom_receiver sau C-STORE)."""
    if not _pacs_internal_token_ok(request):
        return jsonify({'success': False, 'message': 'Forbidden'}), 403
    try:
        payload = request.get_json(silent=True) or {}
        patient_name = (payload.get('patient_name') or '').strip()
        filename = (payload.get('filename') or '').strip()
        if not filename:
            return jsonify({'success': False, 'message': 'Thiếu filename'}), 400
        dicom_path = _resolve_received_dicom_path(patient_name, filename)
        if not dicom_path:
            return jsonify({'success': False, 'message': 'Không tìm thấy file DICOM'}), 404
        uploaded = _orthanc_upload_dicom_file(dicom_path)
        study_uid = ''
        try:
            import pydicom
            ds = pydicom.dcmread(str(dicom_path), stop_before_pixels=True, force=True)
            study_uid = str(ds.get('StudyInstanceUID', '') or '').strip()
        except Exception:
            pass
        orthanc_study_id = _orthanc_find_study_id_by_uid(study_uid) if study_uid else None
        return jsonify({
            'success': uploaded,
            'uploaded': uploaded,
            'study_instance_uid': study_uid,
            'orthanc_study_id': orthanc_study_id,
        })
    except Exception as e:
        return jsonify({'success': False, 'message': str(e)}), 500


def _orthanc_ui_base_url(base_url: str, username: str, password: str) -> str:
    """
    Prefer Orthanc Explorer 2 (/ui/app/) if available, otherwise fallback to
    classic explorer (/app/explorer.html).
    """
    auth_raw = f"{username}:{password}".encode('utf-8')
    auth_header = 'Basic ' + base64.b64encode(auth_raw).decode('ascii')
    # New OE2 route
    try:
        probe = urllib.request.Request(f"{base_url}/ui/app/", method='GET')
        probe.add_header('Authorization', auth_header)
        with urllib.request.urlopen(probe, timeout=2):
            return f"{base_url}/ui/app/"
    except Exception:
        pass
    # Some builds expose /ui/ directly
    try:
        probe = urllib.request.Request(f"{base_url}/ui/", method='GET')
        probe.add_header('Authorization', auth_header)
        with urllib.request.urlopen(probe, timeout=2):
            return f"{base_url}/ui/"
    except Exception:
        return f"{base_url}/app/explorer.html"

@app.route('/api/vr-pacs/orthanc-link/<path:patient_name>/<path:filename>', methods=['GET'])
@_require_staff_api_access
def vr_pacs_get_orthanc_link(patient_name, filename):
    """Map local DICOM to Orthanc study and return direct viewer link."""
    try:
        dicom_path = _resolve_received_dicom_path(patient_name, filename)
        if not dicom_path:
            return jsonify({'success': False, 'error': 'File không tồn tại'}), 404

        import pydicom
        ds = pydicom.dcmread(str(dicom_path), stop_before_pixels=True, force=True)
        study_uid = str(ds.get("StudyInstanceUID", "") or "").strip()
        if not study_uid:
            return jsonify({'success': False, 'error': 'DICOM không có StudyInstanceUID'}), 400

        orthanc_study_id = _orthanc_find_study_id_by_uid(study_uid)
        base_url, username, password = _get_orthanc_settings()
        ui_base = _orthanc_ui_base_url(base_url, username, password)

        # Auto-sync fallback: nếu chưa có trên Orthanc thì tự upload rồi tra lại.
        if not orthanc_study_id:
            uploaded = _orthanc_upload_dicom_file(dicom_path)
            if uploaded:
                orthanc_study_id = _orthanc_find_study_id_by_uid(study_uid)

        if not orthanc_study_id:
            return jsonify({
                'success': False,
                'error': 'Chưa tìm thấy study trên Orthanc',
                'study_instance_uid': study_uid,
                'orthanc_ui_url': ui_base
            }), 404

        if '/ui/' in ui_base:
            study_url = f"{base_url}/ui/app/#/studies/{orthanc_study_id}"
        else:
            study_url = ui_base
        return jsonify({
            'success': True,
            'study_instance_uid': study_uid,
            'orthanc_study_id': orthanc_study_id,
            'orthanc_ui_url': ui_base,
            'orthanc_study_url': study_url,
            'orthanc_rest_study_url': f"{base_url}/studies/{orthanc_study_id}"
        })
    except Exception as e:
        return jsonify({'success': False, 'error': str(e)}), 500

# ==================== AI ASSISTANT LEARNING MODELS ====================
class AIInteraction(db.Model):
    """Lưu trữ tất cả tương tác với AI để học"""
    id = db.Column(db.Integer, primary_key=True)
    original_message = db.Column(db.Text, nullable=False)  # Message gốc từ người dùng
    normalized_message = db.Column(db.Text, nullable=False)  # Message đã chuẩn hóa
    detected_intent = db.Column(db.String(100))  # Intent được phát hiện (search_patient, navigate, etc.)
    confidence = db.Column(db.Float, default=0.0)  # Độ tin cậy (0-1)
    action_taken = db.Column(db.Text)  # Action đã thực hiện (JSON)
    success = db.Column(db.Boolean, default=True)  # Thành công hay không
    user_feedback = db.Column(db.String(20))  # positive, negative, neutral
    context_page = db.Column(db.String(200))  # Trang hiện tại
    created_at = db.Column(db.DateTime, default=datetime.utcnow)
    
class AILearnedPattern(db.Model):
    """Các pattern đã học được từ tương tác"""
    id = db.Column(db.Integer, primary_key=True)
    intent = db.Column(db.String(100), nullable=False)  # Loại intent
    pattern = db.Column(db.Text, nullable=False)  # Pattern text
    keywords = db.Column(db.Text)  # Keywords liên quan (JSON array)
    confidence_score = db.Column(db.Float, default=0.5)  # Điểm tin cậy
    usage_count = db.Column(db.Integer, default=1)  # Số lần sử dụng
    success_count = db.Column(db.Integer, default=1)  # Số lần thành công
    last_used = db.Column(db.DateTime, default=datetime.utcnow)
    created_at = db.Column(db.DateTime, default=datetime.utcnow)
    
class AIKnowledgeBase(db.Model):
    """Knowledge base cho các thông tin và câu trả lời"""
    id = db.Column(db.Integer, primary_key=True)
    question_pattern = db.Column(db.Text, nullable=False)  # Pattern câu hỏi
    response = db.Column(db.Text, nullable=False)  # Câu trả lời
    category = db.Column(db.String(100))  # Loại: info, navigation, etc.
    usage_count = db.Column(db.Integer, default=1)
    accuracy = db.Column(db.Float, default=1.0)  # Độ chính xác (0-1)
    created_at = db.Column(db.DateTime, default=datetime.utcnow)
    updated_at = db.Column(db.DateTime, default=datetime.utcnow, onupdate=datetime.utcnow)

# ==================== AI LEARNING FUNCTIONS ====================
def learn_from_interaction(message, intent, confidence, keywords_dict):
    """Học từ tương tác thành công - cải thiện patterns và keywords"""
    try:
        # Tìm pattern tương tự đã có
        existing_pattern = AILearnedPattern.query.filter_by(
            intent=intent
        ).filter(
            AILearnedPattern.pattern.like(f'%{message[:30]}%')
        ).first()
        
        if existing_pattern:
            # Cập nhật pattern hiện có
            existing_pattern.usage_count += 1
            existing_pattern.success_count += 1
            existing_pattern.confidence_score = (
                existing_pattern.confidence_score * 0.7 + confidence * 0.3
            )
            existing_pattern.last_used = datetime.utcnow()
            
            # Cập nhật keywords nếu cần
            current_keywords = json.loads(existing_pattern.keywords) if existing_pattern.keywords else []
            # Thêm keywords mới từ message nếu chưa có
            message_words = message.split()
            for word in message_words:
                if len(word) > 2 and word.lower() not in [kw.lower() for kw in current_keywords]:
                    # Chỉ thêm từ có ý nghĩa (loại bỏ từ phổ biến)
                    common_words = ['the', 'a', 'an', 'is', 'are', 'was', 'were', 'của', 'và', 'với', 'cho', 'để']
                    if word.lower() not in common_words:
                        current_keywords.append(word)
            
            existing_pattern.keywords = json.dumps(current_keywords[:20])  # Giới hạn 20 keywords
        else:
            # Tạo pattern mới
            # Trích xuất keywords từ message
            learned_keywords = []
            if intent in keywords_dict:
                learned_keywords = keywords_dict[intent].copy()
            
            # Thêm từ trong message nếu có ý nghĩa
            message_words = message.split()
            for word in message_words:
                if len(word) > 2:
                    if word.lower() not in [kw.lower() for kw in learned_keywords]:
                        learned_keywords.append(word)
            
            new_pattern = AILearnedPattern(
                intent=intent,
                pattern=message[:200],  # Lưu 200 ký tự đầu
                keywords=json.dumps(learned_keywords[:20]),
                confidence_score=confidence,
                usage_count=1,
                success_count=1
            )
            db.session.add(new_pattern)
        
        db.session.commit()
        _ai_invalidate_learning_cache()
        
    except Exception as e:
        print(f"Error learning from interaction: {e}")
        db.session.rollback()

def analyze_and_improve_patterns():
    """Phân tích interactions và cải thiện patterns"""
    try:
        # Lấy các interactions gần đây (7 ngày)
        from datetime import timedelta
        cutoff_date = datetime.utcnow() - timedelta(days=7)
        
        interactions = AIInteraction.query.filter(
            AIInteraction.created_at >= cutoff_date
        ).all()
        
        # Nhóm theo intent
        intent_stats = {}
        for interaction in interactions:
            if interaction.detected_intent:
                intent = interaction.detected_intent
                if intent not in intent_stats:
                    intent_stats[intent] = {'total': 0, 'success': 0, 'messages': []}
                
                intent_stats[intent]['total'] += 1
                if interaction.success:
                    intent_stats[intent]['success'] += 1
                intent_stats[intent]['messages'].append(interaction.normalized_message)
        
        # Cập nhật confidence scores dựa trên success rate
        for intent, stats in intent_stats.items():
            success_rate = stats['success'] / stats['total'] if stats['total'] > 0 else 0
            
            patterns = AILearnedPattern.query.filter_by(intent=intent).all()
            for pattern in patterns:
                # Cập nhật confidence dựa trên success rate tổng thể
                pattern.confidence_score = (
                    pattern.confidence_score * 0.6 + success_rate * 0.4
                )
                
                # Tìm keywords mới từ successful messages
                successful_messages = [
                    msg for msg, interaction in zip(stats['messages'], interactions)
                    if interaction.success and interaction.detected_intent == intent
                ]
                
                if successful_messages:
                    # Trích xuất keywords mới
                    current_keywords = json.loads(pattern.keywords) if pattern.keywords else []
                    for msg in successful_messages[:10]:  # Chỉ xem 10 message đầu
                        words = msg.lower().split()
                        for word in words:
                            if len(word) > 2 and word not in current_keywords:
                                current_keywords.append(word)
                    
                    pattern.keywords = json.dumps(current_keywords[:20])
                    pattern.last_used = datetime.utcnow()
        
        db.session.commit()
        
    except Exception as e:
        print(f"Error analyzing patterns: {e}")
        db.session.rollback()


